(word_id,language_id,pos_id,definition,example)
VALUES
(3774,3,1,'ဆဋ္ဌမမွန်ဗျည်း။',NULL)
,(3775,3,4,'၁။ စားသည်။ ဝါး၍မျိုသည်။','စပုၚ် = ထမင်းစားသည်။')
,(3775,3,4,'၂။ အသက်မွေးဝမ်း ကျောင်း တစ်ခုခုကိုပြုသည်။ လုပ်စားသည်။','‘သွံစဖျာ’ = ‘ဈေးရောင်းစားသည်။’ || ‘ကၠောန်စဗ္ၚ’ = ‘လယ်လုပ်စားသည်။’')
,(3775,3,4,'၃။ (ဖိနပ်ကြမ်းတမ်း၍ ခြေကို) ပွန်းပဲ့စေသည်။','“ဓနပ်ဂှ် စ ကၠေံဇိုၚ်တြုံဂှ်ပၠန်ရ။” (ဇ—၂၃၁။ အစွောံ။) = “ထိုဖိနပ်သည် ထိုယောကျာ်း၏ခြေကို ပွန်းပဲ့စေ၏။”')
,(3775,3,4,'၄။ ပျောက်ပျက်ပြုန်းတီးစေသည်။ စားသည်။ တိုက်စားသည်။','“ဍာ်စကၠေံတုဲ သြၚ်ဂှ် လာ်အာရ။” = “ရေတိုက်စား၍ ကမ်းပြိုသွားသည်။”')
,(3775,3,4,'၅။ (သင်္ချာ) စားသည်။','“(၂ဝ) စကဵု (၅) မ္ဂး ဂွံ (၄) ရ။” = “(၂ဝ) ကို (၅) နှင့်စားသော် (၄) ရသည်။”')
,(3776,3,4,'၁။ ခိုင်းသည်။','“(သၟိၚ်) စကာမၞိဟ် ကဵုအာဗက်ရံၚ်ရ။” (ဇ—၂၈၁။ အစွောံ။) = “မင်းသည် လူတစ်ယောက်ကိုခိုင်း၍ လိုက်ကြည့််စေ၏။”')
,(3776,3,4,'၂။ သုံးသည်။ အသုံးပြုသည်။','“မၞိဟ်ဏအ်မွဲဂှ် ဒၞာဲလဵုလေဝ် စကာဟွံဂွံရ။” = “ဤလူတစ်ယောက်သည် ဘယ်နေရာမှ သုံးစားလို့မရဘူး။” || “ချူလိက်မန်မ္ဂး စကာဝေါဟာရမန်ဍာံဍာံညိ။” = “မွန်စာရေးလျှင် မွန်ဝေါ ဟာရစစ်စစ်ကို သုံးပါ။”')
,(3777,3,1,'စာရေး။','တခဳဗ္ၜတ်တဝ်တိ = မြေတိုင်းစာရေး။')
,(3778,3,4,'ခေတ်စားသည်။',NULL)
,(3779,3,1,'တင်ပါး။',NULL)
,(3780,3,1,'တင်ပါးဆုံ။ ခါးစောင်း။',NULL)
,(3781,3,4,'ပုခုံးထက်တွင်တင်ထမ်း၍ သယ်ဆောင်သည်။','‘တ္ၚိန်’ ရှု။')
,(3782,3,4,'စားဝင်သည်။ စာမြိန်သည်။','စစှ်ေတိက်လှိၚ် = စားဝင်အိပ်ပျော်သည်။')
,(3783,3,4,'အစားကြီးသည်။ အစားပုပ်သည်။ အစားကြူးသည်။',NULL)
,(3784,3,4,'‘စ္ဍး’ ရှု။',NULL)
,(3785,3,1,'မြို့စား။','စဍုၚ်မတ္တမ = မုတ္တမမြို့စား။')
,(3786,3,4,'လိုက်သည်။ အစဉ်တစိုက်လိုက်သည်။ (ပါဠိ—အနုဗန္ဓတိ)',NULL)
,(3787,3,1,'ထိမှန်အောင်ပစ်နိုင်စွမ်း။ ပစ်မှတ်။','“(ဗောဓိသတ်ဒှ်သၟာတ္ၚဒယှ်) မၞုံစဍာံမဟွံဆောတ် မၞုံပရှ်မွဲဖရိပ်ဇုက်လလဳဂှ် ထပှ်ဝါပန်ဂတာပ်။” (ဇ—၁၈၁။ အစွောံ။) = “ဘုရားလောင်းသည် လေးသမားကျော်ဖြစ်၍ ပစ်မှတ်ကို မချွတ်မယွင်းပစ်နိုင်စွမ်းရှိ၍ လျှပ်တစ်ပြက်အတွင်း ခုနစ်ကြိမ်ပစ်နိုင်သော အမြန်နှုန်းရှိ၏။”')
,(3787,3,3,'(ဟောသည့်အတိုင်း) မှန်သော။ မချွတ်သော။ မလွဲသော။','“အဲအာသၟာန်အ္စာနိမိတ် မစဍာံမစၟတ်တံဂှ်တုဲ။” (ဇ—၅၃၁။ အစွောံ။) = “နိမိတ်ဖတ်ရာတွင် မချွတ်မလွဲမှန်သော နိမိတ်ဆရာတို့ကို ငါသွား၍မေးသည်ရှိသော်။”')
,(3788,3,4,'ကောက်ကျစ်သည်။',NULL)
,(3789,3,11,'(န) စဏ္ဍာလ။ ဒွန်းစဏ္ဍား။ သူတောင်းစား။ (ပါဠိ—စဏ္ဍာလ)','“ဗောဓိသတ်ပိုဲ ဒှ်ပ္ဍဲဂကူစဏာ—။” (ဇ—၁၇၉။ အစွောံ။) = “ဘုရားလောင်းသည် ဒွန်းစဏ္ဍားအမျိုး­ဖြစ်၍—။” (ညောင်ကန်)')
,(3790,3,6,'အစား၊ ကိုယ်စား။','မၞိဟ်စၞး၊ ညးစၞး = ကိုယ်စားလှယ်။ “အပါအာဝါစၞးအဲရ။” = “ကျွန်တော့်ကိုယ်စား အဖေလယ်တောသွားသည်။”')
,(3790,3,1,'အစား။','“စၞးဒးပၠေၚ်သြန် ပ္ဍဲမရာန်သုၚ်အရက်ဂှ် ရာန်စကွာၚ်ဂှ် ခိုဟ်ဂၠိုၚ်ရ။” = “အရက်ဝယ်သောက်ပြီး ငွေဖြုန်းမည့်အစား မုန့်ဝယ်စားသည်က ပို၍ကောင်းသည်။”')
,(3791,3,1,'‘စၞိန်’ ရှု။',NULL)
,(3792,3,1,'‘စၞာဲ’ ရှု။',NULL)
,(3793,3,1,'စတုဂံ။',NULL)
,(3794,3,11,'(န) ထောပတ်၊ ပျားရည်၊ သကာ၊ နှမ်းဆီ ဤလေးမျိုးကို ရောထားသောဆေး။ စတုမဓူ။','(ပါဠိ—စတုမဓုရ) (= ရှ်မိပ်ပန်သာ်)')
,(3795,3,11,'(န) ၁။ မြင်းမိုရ်တောင်၏ အရပ်လေးမျက်နှာ­ အုပ်စိုးနေကြသော နတ်မင်းကြီးလေးပါး။',NULL)
,(3795,3,11,'(န) ၂။ ယင်းနတ်မင်းကြီးများနေသော၊ နတ်ပြည်ခြောက်ထပ်တွင် အောက်ဆုံးနတ်ပြည်။ စတုမဟာရာဇ်။ (ပါဠိ—စတုမဟာရာဇ)',NULL)
,(3796,3,11,'(န) စစ်အၚ်္ဂါလေးပါး။',NULL)
,(3797,3,1,'အနားလေးဖက်ညီ ထောင့်မှန်ပုံ။ စတုရန်း။',NULL)
,(3798,3,10,'(န) လောကကိုစောင့်ရှောက်သော နတ်မင်းကြီးလေးပါး။','(၁၊ အရှေ့ — ဓတရဋ္ဌနတ်မင်း။ ၂၊ တောင်—ဝိရုဠကနတ်မင်း။ ၃၊ အနောက်—ဝိရူပက္ခနတ်မင်း။ ၄၊ မြောက်— ကုဝေရနတ်မင်း။)')
,(3799,3,10,'(နဝိ) လေးခုမြောက်ဖြစ်သော။ စတုတ္ထ။',NULL)
,(3800,3,10,'တစ်ဆယ့်လေးရက်မြောက်သောနေ့။',NULL)
,(3801,3,1,'လောင်ခြင်း။','သ္ၚိစၞံၚ် = အလောင်းစင်။ လူသေအလောင်းကို မီးသင်းဂြိုဟ်သည့် ထင်းပုံ။ ‘စံၚ်’ (ကြိ) လည်းရှု။')
,(3802,3,1,'လက်ညှိုး။ (ပါဠိ—တဇ္ဇနဳ)',NULL)
,(3803,3,1,'‘စၞိန်’ ရှု။',NULL)
,(3804,3,4,'‘စၞိန်ကြဴကၠေံ’ ရှု။',NULL)
,(3805,3,4,'မျှော်သည်။',NULL)
,(3806,3,1,'စစ်ဆေးသည်၊—ခြင်း။ စိစစ်သည်၊—ခြင်း။','“ဗကမှာဗြီုဂှ် ဖေက်ဘဲကျာ် စၟဳစၟတ်။ (ဝါ) ဖေက်ဘဲစၟဳစၟတ်ကျာ်။” (ဇ—၄ဝ၅။ အစွောံ။) = “ဗကဗြဟ္မာသည် မြတ်စွာဘုရား ၏စစ်ဆေးခြင်းကို ကြောက်သည်။”')
,(3807,3,4,'လှမ်းမြင်သည်။','“(ညးဗၞိက်လီုသမၠီုဂှ်) ဒြေပ်ဗက်လမာ်ဇိုၚ်ဗောဓိသတ်ရ၊ စိုပ်သြၚ်ကြုၚ် စၟဳညာတ်ဗောဓိသတ်ပ္ဍဲဂၠုၚ်ရ။” (ဇ—၃။ အစွောံ။) = “ရွဲကုန်သည်မိုက်သည် ဘုရားလောင်း၏ခြေရာအစဉ်ကို လိုက်သည်ရှိသော် မြစ်နားသို့ရောက်၍ လှေ­သွားသော ဘုရားလောင်းကို လှမ်းမြင်၏။”')
,(3808,3,4,'စောင့်မျှော်သည်။',NULL)
,(3809,3,4,'(အဝေးမှ) လှမ်းကြည့်သည်။',NULL)
,(3810,3,1,'ကြက်ငှက်နှုတ်သီး။','စမဴအဒါ = ဝမ်းဘဲနှုတ်သီး။')
,(3811,3,1,'နန်းတော်နှင့် ကျောင်းတော်တို့၏ အဝင်အထွက် အဆောင်ငယ်။ စမုတ်ဆောင်။','(‘စမုတ်’ ဟူသော ဤမြန်မာဝေါဟာရသည် ‘စမုက်’ ဟူသော မွန်ဝေါဟာရမှ ဆင်းသက်လာသည်။) || ဒုၚ်စမုက် = (ဘုရင်)အခစားခံသည်။ || ရုၚ်စမုက် = စမုတ်ဆောင်။ || “တိုန်စိုပ်မုက် ရၚ်စမုက်သၟိၚ် နရိုအ်ပ္တီသၟိၚ်။” (ဇ—၁၃၁။ အစွောံ။) = “မင်းရင်ပြင်သို့သွား၍ ဟစ်ကြွေးခြင်း ကို ပြုကုန်၏။” (ညောင်ကန်)')
,(3812,3,1,'ကြောက်ခြင်း။ အကြောက်။','“ယွံမၚ်ဗၠာဲ၊ သမ္ဘာနာဲပိုဲဂှ်လေဝ် တၠရုပ်တၠကယိုၚ်ရောၚ်။ ဋ္ဌာန်တြဴဒမၠမဂစိုတ်ညးဂှ် နာဲပိုဲတံညးၜါ သမ္ဘာကဵုတၠသ္ၚိဂှ် လ္ပအာညိ” ညးကွာန်တံဂှ်ဂး။ မၚ်ဗၠာဲကၞပ်ဒၟံၚ်ဟွံဟီု၊ ဟီုပစမိုက်ပ္ဍဲစိုတ်တုဲ အာတဴရ။ (ဇ—၃၇၄။ အစွောံ။) = “အိုလုလင်၊ သင့်မယားသည်လည်း ရုပ်အဆင်းရှင် အဆင်တန်ဆာရှင်မိန်းမတည်း။ လူသတ်ဓါးပြတို့ရှိသော ဤလမ်းခရီး­ သင်တို့မသွားကြကုန်လင့်” ဟုရွာသားများဆို၏။ လုလင်သည် ဘာမျှမပြောဘဲ ဆိတ်ဆိတ်နေ၏။ အကြောက်ကို စိတ်ထဲ­သာထား၍ သွားသည်သာလျှင်တည်း။ || “(ဂတာံတၠ ညာဏ်ဂှ် ပံက်စၞာဲသၟိက်ဖအိုတ်လမျီုဇကု သၟိက်စဖျုန်ဇကုတုဲ ဟီုဘကမၠဇကုဂှ်) ၜိုန်မိၚ်ဒၟံၚ်ကီု ဇမိုက်ဟွံမွဲ။” (ဇ—၃၈။ အစွောံ။) = “ဉာဏ်ရှင်ဖြစ်သောဗုဇွန်သည် ဗျိုင်းစဉ်းလဲက မိမိအသက် ကိုသတ်လို၍ မိမိအသားကိုစားလို၍ မိမိအား ပြောဆိုခြိမ်းခြောက်သည်ကို ကြားရသော်လည်း အကြောက်မရှိ။” || “တၟံသိနနရာတ်တၠအစောံဂှ် ၜိုန်ဒှ်ကီု ကျာလေၚ်ကဝ် ပိုက်ကသဳဗ္ဒောံပြောံကၠေံတုဲ ဆုသၟာဲသၟဇွဂၞိၚ်အပြောံတံဂှ် မူရဴအလေဝ်ကျာလေၚ်ကဝ် မသ္ပစမိုက်နွံတုန်ရော။” (ဇ—၂၅၁။ အစွောံ။) = “အစွမ်းကြီးစွာသော မြင်းမိုရ်တောင်ကိုပင်လည်း ကမ္ဘာဖျက်လေသည် တိုက်လှုပ် လှဲဖြိုပစ်နိုင်သေး၏။ ဆွေးမြည့်လေပြီးသော အချည်းနှီးသောသစ်ပုပ်မျှကို ကမ္ဘာဖျက်လေသည် အဘယ်မူ၍ ကြောက်ရွံ့ခန့်ညားခြင်း ပြုပါငြားအံ့နည်း။” ‘မသက္ကုစမိုက်/ဇမိုက်’ လည်းရှု။')
,(3813,3,4,'ဆင်တူသည်။','‘သမုၚ်’ (ကြိ)ရှု။')
,(3814,3,4,'၁။ စစ်ဆေးသည်။','စၟတ်အမှု = အမှုစစ်ဆေးသည်။')
,(3814,3,4,'၂။ မှတ်သားသည်။','“စရၚ်ဂတှ်အဲဒးလေဲဂှ် စၟတ်လဝ်ဗိုန်န်ညိ။” = “ငါလျော်ရမည့် အကြွေးစာရင်းကို သေချာစွာ မှတ်ထားပါ။”')
,(3814,3,1,'မှန်ကန်ခြင်း။ အမှန်။','“ဂလာန်မဟွံဒှ်စၟတ်ဂှ် လ္ပဟီုညိ၊ ဂလာန်မဒှ်စၟတ်ဂှ် ဟီုညိ။” = “မမှန်သောစကားကို မပြောပါနှင့်၊ မှန်သောစကားကို ပြောပါ။” || ဗွဲစၟတ် (ကြိဝိ) = မှန်ကန်စွာ၊ အမှန်စင်စစ်။')
,(3815,3,4,'မှတ်သားသည်။','(န) မှတ်သားခြင်း။ အမှတ်အသား။')
,(3815,3,1,'မှတ်သားခြင်း။ အမှတ်အသား။',NULL)
,(3816,3,1,'အုပ်စိုးခြင်း။ အကြီးအမှူး။ အာဏာ။','“ယွံတၠညး မဒှ်စ္ၜုဲစ္ၜော်လိုက်အိုဿီု၊ တၠညးမ ဒှ်စမိန်သတ်ဂမၠိုၚ်ရောၚ်။” (ဇ—၄၃၂။ အစွောံ။) = “လူအပေါင်းတို့၏ ကိုးကွယ်ရာဖြစ်သော အရှင်မင်းကြီး၊ အရှင်သည် သတ္တဝါအပေါင်းတို့၏ အကြီးအမှူးဖြစ်၏။” || အာစိုပ်ပ္ဍဲစၟိန်ဗြဴ = မိန်းမ အလိုသို့ လိုက်သည်။')
,(3817,3,1,'‘စမိန်ပြမာန်’ နှင့်အတူတူ။','“အဲတုန်လေဝ် ဒှ်စမိန်စမာန်ဗြဴတုဲ ဟွံရိုဟ် စလမျီုတုဲ မဒးကၠုၚ်ကၠတ်ကေတ်ဒြပ်သၟိၚ်—။” (ဇ—၃ဝ၉။ အစွောံ။) = “အကြင်ငါသည် မိန်းမအလိုသို့လိုက်၍ ကိုယ့်အသက်ကို မရေတွက်ဘဲ (မင်း၏ဥစ္စာကို) ခိုး၏။” (ညောင်ကန်)')
,(3818,3,1,'အုပ်စိုးခြင်း။ အုပ်ချုပ်ခြင်း။ အစိုးရခြင်း။ အလို။','“လ္ပအာစိုပ်စမိန်ပြ မာန်လောဘညိ။” (ဇ—၄၂။ အစွောံ။) = “လောဘ၏အလိုသို့ မလိုက်ပါနှင့်။” || “ဟိုတ်အဲဍိက် မတဴပ္ဍဲစၟိန်ပြမာန်ဒေါသတုဲ ကောန်ၚာ်မဂစိုတ်ကောန်အဲဂှ် အကဵုကၠစကၠေံ ဍေံချိုတ်အာတုဲရ” ကြေဲ ဗြဴဂးကဵုသၟိၚ်။ (ဇ—၃၄၃။ အစွောံ။) = “အကျွန်ုပ်သည် ဒေါသ၏အလိုသို့ လိုက်သည်ဖြစ်၍ အကျွန်ုပ်သားအား သတ်သောကလေးကို ကျားကိုစားစေ၍ သေလေပြီ။” || “တြုံမဒှ်စၟိန်ပြမာန်ဗြဴမွဲ ဂပ်ဂဝ်က္ဍုဟ် ဂပ်ဂဝ်ဂရိုဟ်။” (ဇ—၁၃။ အစွောံ။) = “မိန်းမ၏အုပ်စိုးခြင်းကို ခံရသောယောကျာ်းသည်လည်း ရွံရှာအပ် ကဲ့ရဲ့အပ်၏။” || “သတ္တအ်ဂမၠိုၚ်ဝွံ မဒးဒှ်စၟိန်ပြမာန်သၟိၚ်ဂစိုတ်ဖအိုတ်ရ။” = “သတ္တဝါအပေါင်းတို့သည် သေမင်း၏အစိုးရခြင်းသို့ အားလုံးရောက်ကြရ၏။”')
,(3818,3,4,'အုပ်စိုးသည်။ အုပ်ချုပ်သည်။ အစိုးရသည်။','“ဗောဓိသတ်ပိုဲဒှ်သၟိၚ်အိန် ဂွံစၟိန်ပြမာန်သွဝ်ၜါ။” (ဇ—၃၉၁။ အစွောံ။) = “ဘုရားလောင်းသည် သိကြားမင်းဖြစ်၍ နတ်ပြည်နှစ်ထပ်ကို အစိုးရ၏။” || “ယွံသၟိၚ်မစမိန်ပြမာန်လဝ်မှာဇန်ဂမၠိုၚ်—။” (ဇ—၁၈၆။ အစွောံ။) = “ပြည်သူအပေါင်းကို အစိုးရသောဘုရင်မင်းမြတ်။” || “ကျာ်တြဲဂှ် မဂွံစမိန်ပြမာန်တဴပြကိုဟ်အဘိဓဝ် မလၞိန်ဗပိန်ကၠေံဝါဒညးအိုဿီု—။” (ဇ—၂၂၉။ အစွောံ။) = “မြတ်စွာဘုရားသည် အဘိဓမ္မာကျမ်းကို အစိုးရ၍ သူတစ်ပါးတို့၏အယူဝါဒကို နင်းခြေဖျက်ဆီးပစ်နိုင်၏။” ‘စၟိန်စၟာန်’ ဟု၄င်း ‘ပြမိန်ပြမာန်’ ဟု၄င်း အနည်းအားဖြင့်တွေ့ရသည်။')
,(3819,3,4,'(ပုခုံးတွင်)လွယ်သည်။','စမာဲထိုၚ် = လွယ်အိတ်လွယ်သည်။ || ထိုၚ်စမာဲ = လွယ်အိတ်။ || “ဗောဓိသတ်ဒှ်ညးဗၞိက်လီု ထိုၚ်မစမာဲဏာပ္ဍဲပါၚ်ကၞက်တုဲ ဂ္ၚေၚ်သွံလီုရ။” = “ဘုရားလောင်းသည် ရွဲကုန်သည်ဖြစ်၍ အိတ်ကို ချိုင်းကြား­လွယ်လျက် ရွဲတို့ကို လှည့်လည်ရောင်း၏။”')
,(3820,3,1,'လက်ဆောင်ပဏ္ဏာ။','“အမာတ်တံညးလ္ၚီ ကၠုၚ်ဆက်စၟာဲစၟိန် ကုသၟိၚ်ဂှ်အိုတ်ရ။” (ဇ—၅၃၆။ အစွောံ။) = “တစ်ထောင်ကုန်သောအမတ်တို့သည် ထိုမင်းအား လက်ဆောင်ပဏ္ဏာဆက်ကြကုန်၏။” || “ပဏ္ဏာကာရ စမာဲစမိန်ဂမၠိုၚ်ဟေၚ် ညးဍုၚ်တံဝွံဂှ် ကွာဲလဗာဲတဴရ။” (ဇ—၁၂၅။ အစွောံ။) = “လက်ဆောင်ပဏ္ဏာများစွာကို မြို့သားမားက ဆက်သကြကုန်၏။” || ‘တၟာဲဇမိန်’ နှင့်အတူတူ။')
,(3821,3,11,'(န) သားမြီးယပ်။',NULL)
,(3822,3,3,'‘စၟဟ်’ ရှု။',NULL)
,(3823,3,4,'(ရေ)ဖျန်းသည်။',NULL)
,(3824,3,1,'ဂိုဏ်းသင့်ခြင်း။','ဒးစရဲအ္စာ = ဆရာဂိုဏ်းသင့်သည်။')
,(3825,3,4,'‘သြဲ’ (ကြိ) ရှု။',NULL)
,(3826,3,1,'တားခြစ်ထားသောမျဉ်း။',NULL)
,(3826,3,4,'တားခြစ်သည်။','“စရက်တိ နကဵုဒစုန်” = “တောင်ဝှေးဖြင့် မြေကြီးကို မျဉ်းတားသကဲ့သို့ခြစ်သည်။”')
,(3827,3,1,'အစိတ်။ အခြမ်း။','“(လၟာဲဂှ်) ဍေံရပ်ဂွံလေံတရေက်တုဲ ဍေံ လၟိုတ်စးကၞုဲတုဲ—။” (ဇ—၂၄၉။ အစွောံ။) = “ထိုမျောက်ကို ထိုအလမ္ပာယ်သည် ဝါးခြမ်းပြားနှင့် ကျောက်­ရိုက်၍—။” (ညောင်ကန်) || “နဒုန်စရေက် တက်စုတ်ပိလစုတ်ရ။” (ဇ—၂၅၂။ အစွောံ။) = “ဝါးခြမ်းစိတ်ကိုကိုင်၍ — သုံးကြိမ်ကျော­ရိုက်၏။” (ညောင်ကန်)')
,(3827,3,9,'အခြမ်း၊ အစိတ်ကို ရေတွက်ရာတွင် သုံးသောစကားလုံး။','ဒုန်ပိစရေက်၊ ဒုန်ပိတရေက် = ဝါးသုံးခြမ်း။')
,(3827,3,4,'ခြမ်းသည်။ ခွဲသည်။','“ကြုက်ဂှ် ကရေက်ထောံအဒေါဝ်ညိ။” = “သရက်သီးကို အလယ်ခြမ်းလိုက်ပါ။”')
,(3828,3,1,'‘သြော်’ (?)','“ပ္ဍဲဋ္ဌာန်သုသာန်စရော် ဋ္ဌာန်ဒၟံၚ်မိဗှ်ေဂှ် မဒှ်ဂ္ၚေၚ်မတုဲရ။” (ဇ—၁၆ဝ။ အစွောံ။)')
,(3829,3,4,'၁။ (ထီးစသည်) မိုးကာသည်။',NULL)
,(3829,3,4,'၂။ ဝတ်သည်။ ဝတ်ဆင်သည်။','“သေဋ္ဌဳဗာရာဏသဳဂှ် စရံက်လစိန် ဗိုက်ယာတ်ကၠေဟ်ယာတ်ကမှိဟ် မတိုန်သဳကၠဳ(သၟိၚ်)—။” (ဇ—၅၃။ အစွောံ။) = “ဗာရာဏသီသူဌေးသည် လက်စွပ်ကိုဝတ်၍ ကောင်းသောအဝတ်ပုဆိုးကိုဝတ်၍ မင်းကိုခစား ရန်သွား၏။” ‘သြံက်’ (ကြိ)နှင့်အတူတူ။')
,(3829,3,3,'ဝတ်သော။ ဝတ်ဆင်သော။','လစိန်စရံက် = ဝတ်သောလက်စွပ်။ || “လဗၚ်သမုၚ်တံ (ချပ်) ပၠံၚ်ကေတ် လစိန်စရံက်ယာတ်ဗွိုက်(သေဋ္ဌဳ)—။” (ဇ—၅၃။ အစွောံ။) = “သေသောက်ကြူးတို့သည် သူဌေး၏ဝတ်သောလက်စွပ်နှင့် အဝတ်ပုဆိုးတို့ကို လုယူရန်ကြံစည်၏။”')
,(3830,3,4,'(ထီး) ဆောင်းသည်။ မိုးကာသည်။','စရံက်ဗဒဝ်က္ဍိုၚ်ဗ္တာၚ် = ထီးဖြူဆောင်းသည်။ ‘သြံက်ဗဒဝ်’ (ကြိ) နှင့်အတူတူ။')
,(3831,3,1,'အမှု။ ကိစ္စ။ အလုပ်။','စရၚ်ဓဝ်ကုသဵု = ကုသိုလ်အလုပ်။ || စရၚ်ပါပ် = မကောင်းမှု။  || စရၚ်ကိစ္စ၊ ကိစ္စစရၚ် = အမှုကိစ္စ။ အရေးကိစ္စ။ || “ကိစ္စစရၚ်ကေၚ်ကာဓဇဲအိုဿီုတအ်ဂှ် ကောန်စိၚ်ဝွံ ပ္တုဲကဵုဖအိုတ် ရိုဟ်ဟ်တ္ၚဲရ။” (ဇ—၁၅၆။ အစွောံ။) = “ထိုလက်သမားတို့၏ အမှုကိစ္စဟူသမျှကို ထိုဆင်ငယ်သည် နေ့စဉ်နေ့တိုင်း ပြုလုပ်ပေး၏။” || “ယြဴစရၚ်ကိစ္စမွဲဂှ် ဟွံဂွံစဳ စတ်စံၜတ်ဗိုန်က္ညန်တုဲ ဗွဲမပြဟ်ပြေဟ်ဂှ် လ္ပပ္တုဲညိ။” (ဇ—၅၂၁။ အစွောံ။) = “အကြင်အမှုကိစ္စကို သေချာစွာမစိစစ်မစုံစမ်းဘဲ အလျင်စလို မပြုပါနှင့်။” || ‘သရၚ်’ ဟုလည်း ရေးထုံးရှိသည်။')
,(3832,3,1,'စာရင်း။','တော်စရၚ် = စာရင်းတွက်သည်။ || ကံက်စရၚ် = စာရင်းကောက်သည်။ စာရင်းယူသည်။')
,(3833,3,1,'အနီးအနား။ အစွန်းအနား။','“ပ္ဍဲစရၚ်ကတိုၚ်လ္ၚဂှ် (ဗောဓိသတ်)ဒတဴဒၟံၚ်ရ။” (ဇ— ၄ဝ။ အစွောံ။) = “ထိုမီးကျီးတွင်း၏ အစွန်းအနား­ ဘုရားလောင်းရပ်နေ၏။”')
,(3834,3,1,'မကောင်းမှု။ အကုသိုလ်။','‘သရာံပါပ်’ နှင့်အတူတူ။')
,(3835,3,1,'ချောက်။','“ဗြဴသုဇာတာမွဲဂှ် မမိက်ကုသဵုမွဲ ဟွံဂွံပ္တုဲသက်က်တုဲ စုတိအာတုဲ ဒှ်ပံက်ဗြဴမွဲ ပ္ဍဲဂြိုပ်စရၚ်လ္ဂောဝ်ဂှ်ရ။” (ဇ—၃၁။ အစွောံ။) = “သုဇာတာမူကား ကောင်းမှုကိုမပြု သောကြောင့် (စုတေ၍) တခုသောတောဝယ် ချောက်­ ဗျိုင်းငှက်မအဖြစ်ဖြင့်ဖြစ်၏။” (ညောင်ကန်)')
,(3836,3,1,'မြစ်ကူး၊ ချောင်းကူးရေတိမ်ပိုင်း။ ဆိပ်။','“ယြဴဋ္ဌာန်မွဲတုန် ဟိုတ်နူလှိုက်ဍာ်မဂၠိုၚ်ကီု ဟိုတ်မဒှ်စရၚ်လမၠာ်မဟွံသၟဟ်ကီု တြဴမသ္ဇိုဟ် မတိုန်စှ်ေဝါတ်နွံ။” (ဇ—၂၉။ အစွောံ။) = “အကြင်အရပ်­ ညွန်နှင့်ရေများသောကြောင့်၄င်း မညီညွတ်သောဆိပ်ဖြစ်သောကြောင့်၄င်း တက်ဆင်းရန်ခက်ခဲသော နက်သောခရီးသည်ရှိ၏။” || ‘သြၚ်လမၠာ်’ နှင့်အတူတူ။')
,(3837,3,1,'အလိုလိုဖြစ်သောအိုင်။ ထုံးအိုင်။ ဇာတဿရအိုင်။','“(ဗောဓိသတ်ဒှ်သၟိၚ်ဂစေံ) သ္ကဲစရၚ်သာဲမွဲပ္ဍဲဂြိုပ် သီုတွဳဝါရဂမၠိုၚ် ဒၟံၚ်တဴရ။” (ဇ—၁၃၃။ အစွောံ။) = “ဘုရားလောင်းငှက်မင်းသည် တောရှိတစ်ခုသောဇာတဿရအိုင်နား­ အခြံအရံများနှင့်တကွ နေ၏။” || “(ဂစေံဂမၠိုၚ်) ပတုံဖျေံကဏေံ ပ္ဍဲဍာ်စရၚ်ဂှ်တုဲ—။” (ဇ—၁၃၃။ အစွောံ။) = “ငှက်များသည် ထိုဇာတဿရအိုင် ၏ရေ­ ကျင်ကြီးစွန့်ချကုန်၏။”')
,(3838,3,1,'စာရင်းအင်း။',NULL)
,(3839,3,1,'(ဆင်နှင်ရန်သုံးသော) ချွန်း။',NULL)
,(3840,3,1,'?',NULL)
,(3841,3,4,'ကျော်သည်။ ကျော်ဖြတ်သည်။ ဖြတ်သန်းသည်။','“ပ္ဍဲကာလၜိုပ်ၜါ မဂိုၚ်ဏာ ကၞုဟ်ဂှ် လတူအာကာသ စရုၚ်အာလတူဍုၚ်ဗာရာဏသဳ။” (ဇ—၂၁၅။ အစွောံ။) = “နှစ်ခုသော ဟၚ်္သာတို့က လိပ်ကိုချီ၍ အာကာသ­ သယ်ဆောင်သွားစဉ် ဗာရာဏသီမြို့၏အထက်မှ ဖြတ်သန်းသွား၏။” || “နူဂှ် ညးၜါသမ္ဘာကဵုတၠသ္ၚိ စရုၚ်ကၠေံဂြိုပ်ဂှ်တုဲ အာဂွံကွာန်မွဲပၠန်ရ။” (ဇ—၃၇၄။ အစွောံ။) = “ထိုမှ လင်မယားနှစ်ဦးတို့သည် တောကိုဖြတ်ကျော်၍ တစ်ခုသောရွာသို့ ရောက်ပြန်၏။” || “သၟိၚ်ကောသလရးတေံ ဇက်ကၠုၚ်စရုၚ်ကၠောံ မုဟ်ရးဗာရာဏသဳတုဲ လုပ်စိုပ်ဒေါဝ်ရးရ။” (ဇ—၅၁။ အစွောံ။) = “ကောသလပြည်မင်းသည် ဗာရာဏသီတိုင်းစွန်ဒေသကို ချီလာ ဖြတ်ကျော်ပြီးလျှင် တိုင်းလယ်သို့ ဝင်ရောက်၏။” || “ယွံအ္စာပိုဲ၊ ဗမၞးသေတကေတုမွဲ ကောန်စ ဏာမယုတ်ဂကူဂှ် သရုၚ်ကၠေံက္ဍိုပ်တုဲရအဴ။” (ဇ—၃၇၇။ အစွောံ။) = “ဆရာ၊ သေတကေတု ပုဏ္ဏားအား အမျိုးယုတ်သော စဏ္ဍာလက ဦးခေါင်းပေါ်ကျော်ခဲ့ပြီ။” || “ဗမၞးဂှ် သီုမသုန်ကၠံကွဳဂှ် ဇက်သရုၚ်ကၠောံဂြိုပ်ဂှ်ရ။” (ဇ—၅၁၃။ အစွောံ။) = “ထိုပုဏ္ဏားသည် လှည်းငါးရာနှင့်တကွ ထို တောကို ဖြတ်သန်းသွား၏။” || “ဗြဴစရုၚ်ကန္တာဂှ် ကောန်ဍေံချိုတ်အာ ဇွောံဍေံလေဝ်ဟွံမွဲ လအ် သ္ဂောံစိုပ်ဗဒိုပ်ဍုၚ်ကွာန်ရ တၞဟ်နမၚ်မွဲလမျီုညိဂးတုဲ သီုလေပ်ဟွံမာန် မဒးစဖျုန်ကောန်တုဲရ။” (ဇ—၂၅၅။ အစွောံ။) = “ကန္တာရကို ဖြတ်သန်းသောမိန်းမသည် သားသေ၏၊ ရိက္ခာလည်းမရှိသည်ဖြစ်၍ စခန်းမြို့ရွာသို့ မရောက်သေးမီ အသက်ကိုစောင့်အံ့သောငှာ သား၏အသားကို မမျိုရက်ဘဲလျက်လျှင် စားရ၏။”')
,(3842,3,1,'ပုခက်?။ ပုဆိုးသံလျင်။ (ပါဠိ—ပါဋက·)',NULL)
,(3843,3,1,'တံကျင်။ တံသင်း။ ငြောင့်။','စရံၚ်ပသဲ = သံတံကျင်။ || “(တြုံကမၠတ်ဂှ် ညး) ပတိုန် ဆုစရံၚ် ဒုက္ခဝေဒနာဇၞော်ဟေၚ် မဒးစသိုၚ်တဴရ။” (ဇ—၁၄၇။ အစွောံ။) = “ထိုခိုးသူယောကျာ်း အား သစ်တံကျင်ဖြင့် တံကျင်လျှိုကုန်၍ ထိုခိုးသူသည် ကြီးစွာသောဒုက္ခဝေဒနာကို ခံစားရ၏။”')
,(3843,3,4,'တံကျင်လျှိုသည်။','“(တြုံကမၠတ်ဂှ်) ပ္တိတ်ဏာမ္ၚးဍုၚ်တုဲ စရံၚ်ကၠေံလမျီုရ” သၟိၚ်ဂး။ (ဇ—၁၄၇။ အစွောံ။) = “ထိုခိုးသူယောကျာ်းအား မြို့ပြင်သို့ထုတ်၍ တံကျင်လျှို၍သတ်စေ” ဟုမင်းဆို၏။ || ‘သြံၚ်’ ဟုလည်းရေးသည်။')
,(3844,3,1,'ဆူးငြောင့်။ ခလုတ်ကန်သင်း။','“ပ္ဍဲကာလဂှ် အလုံဂတာဇမ္ဗုဒိပ်မွဲ တိသတးညံၚ်ရဴ မုက်ဖံကီုရ၊ စရိုၚ်ဇလဟွံမွဲသက်သက်ရ။” (အဓါန်မသုန်။ အစွောံ) = “ထိုကာလ­ ဇမ္ဗူဒိပ် ကျွန်းအလုံးသည် အိုးစည်မျက်နှာပြင်ကဲ့သို့ မြေသည်ညီညာ၏၊ ဆူးငြောင့်ခလုတ်ကန်သင်း လုံးဝမရှိ။”')
,(3845,3,1,'အရေး။ အကြောင်း။ ခြစ်ရာ။ (ပါဠိ—ရာဇိ)','စရိတ်ေၚက်ဂရး = ထွန်ခြစ်ခြစ်ရာ။ || စရိတ်ဂြိုပ်လမ်စံက် = ညိုသောတောအရေး။ (ပါဠိ—နဳလဝနရာဇိ)')
,(3845,3,4,'အရာဖြစ်အောင်ခြစ်သည်။',NULL)
,(3846,3,1,'နဖူးအရေး။ နဖူးပြင်။ (?)','“အ္စာအဲဂှ် ပ္ဍဲစရိတ်ကၞေၚ်ညးဂှ် ညးစုတ်လဝ်ဂမ်စိုတ် သ္ဂောံချိုတ်တ္ၚဲဝွံရ။” (ဇ—၂၅၂။ အစွောံ။) = “ယနေ့ဆရာသည် နဖူးပြင်ဖြင့် သေမင်းကိုယူ၍ သေအံ့ဟုလာ၏။” (ညောင်ကန်)')
,(3847,3,1,'စရိုက်။ အလေ့အကျင့်။','စိုတ်စရိုတ် = စိတ်နေစိတ်ထား။')
,(3847,3,4,'ဝတ်ရုံသည်။ ဝတ်ဆင်သည်။','ယာတ်စရိုတ် = ဝတ်ဆင်ရန်အဝတ်။ || ဂၞိန်စရိုတ် (ကြိ) (အမျိုးသမီး) ဝတ်ဆင်သည်။ (န) အမျိုးသမီးအဝတ်အစား။ || စရိုတ်လတက် = ဝတ်ဆင်သည်။ || “တၠသ္ၚိရဟွံမွဲ ဂရောပ်လတက်မတန်လ္ၚီ နၚ်ကဵုဂွံစရိုတ်လတက်ကီု ဒှ်ဒၟံၚ်နက်ဂသၠောံဒိုဟ်ကီု” သၟတ်ဗြဴဂး။ (ဇ— ၆၇။ အစွောံ။) = “လင်မရှိသောမိန်းမအား အဖိုးတစ်ထောင်ထိုက်သော အဝတ်အရုံကို ယူလာ ၍ ဝတ်ဆင်စေသော်လည်း အဝတ်မပါ ကိုယ်ချည်းစည်းကဲ့သို့သာဖြစ်၏။”')
,(3848,3,4,'အက်သည်။','စရောန်ပါ် = အက်ကွဲသည်။')
,(3849,3,1,'ဂုဏ်။ ကျက်သရေ။ ခမ်းနားခြင်း။ တင့်တယ်ခြင်း။','ပ္တိုန်ဂုန်စရာဲ = ဂုဏ်ပြုသည်။')
,(3850,3,1,'ဂုဏ်ကျက်သရေ။',NULL)
,(3851,3,1,'ရုပ်အဆင်းအလှ။','“ဇနပဒကလျာဏဳဂှ် မနွံကဵုစရာဲရုပ် မဍိုက်ပေၚ်တဴထမှိက်မသုန်သာ်ရောၚ်။” (ဇ—၉၆။ အစွောံ။) = “ဇနပဒကလျာဏီသည် ရုပ်အဆင်းအလှရှိ၍ ကောင်းခြင်း ငါးဖြာနှင့်ပြည့်စုံ၏။” || “(ဇနပဒကလျာဏဳဂှ်) ပတၠစရာဲရုပ် — ညံၚ်ရဴကောန်ဒေဝတဴအဆေဝ်သွဝ် တံကီု။” (ဇ—၉၆။ အစွောံ။) = “ဇနပဒကလျာဏီသည် နတ်သမီးတို့ကဲ့သို့ ရုပ်အဆင်းအလှပိုၚ် ရှင်ဖြစ်၏။”')
,(3852,3,1,'ညီညာသောကုန်းမြင့်။',NULL)
,(3853,3,1,'တောင်ထိပ်၏ညီညာသောမြေအပြင်။ တောင်ထိပ်မြေပြင်။ (ပါဠိ—အဓိစ္စကာ)','“ပ္ဍဲဨသာန်တိဗ္ၚဂှ် ပ္ဍဲစရုဲတၟအ်မွဲဂှ် ဒမြိုမ်ဂြိုပ်ကြိက်မွဲနွံ။” (ဇ—၄၈၄။ အစွောံ။) (တၟအ် = တောင်) = “လယ်၏အရှေ့မြောက်အရပ်­ကား တခုသောတောင်ထိပ်မြေ ပြင်­ တခုသောလက်ပံတောရှိ၏။”')
,(3854,3,1,'တောအုပ်။','“(ညးပိ) ဇိက်ဗ္ၚ ပ္ဍဲပါၚ်စရုဲဂြိုပ်မွဲ။” (ဇ—၆၇။ အစွောံ။) = “သုံးယောက်ကုန်သောသူတို့သည် တခုသောတောအုပ်၏အဝ­ လယ်ထွန်ကုန်၏။” (ညောင်ကန်)')
,(3855,3,1,'တောအုပ်အစွန်း။ အဝေးမှမြင်ရသော တောအရေး။','“ပတွဵုနူ(စရုဲမုဟ်ဂြိုပ်)ဂှ် အလုံဂြိုပ် ဗြဲဗ္ဂူဒၟံၚ်လၟိုန်။” (ဇ—၁။ အစွောံ။) = “ထိုသို့သောတောအရေးမှစ၍ — မိုဃ်းသည် မပြတ်ရွာ၏။” (ညောင်ကန်) || “ကောန်ကဵုမဂှ် စိုပ်အာစရုဲမုဟ်ဂြိုပ် ဒၞာဲကမၠတ်ဒမၠတံဂှ်ရ။” (ဇ— ၄၅၉။ အစွောံ။) = “သားအဖနှစ်ယောက်တို့သည် အတူတကွ ခရီးသွားကုန်၏။ တောအုပ်အဝ သူခိုးတို့သည် ထကုန်၏။” (ညောင်ကန်) || ‘စ္ၜုဲမုဟ်ဂြိုပ်’ လည်းရှု။ || ‘စမြုဲမုဟ်ဂြိုပ်’ နှင့် အတူတူ။')
,(3856,3,1,'ပျက်ရယ်ပြုခြင်း။','ပစရဵု၊ ပဂရိုၚ်စရဵု၊ ဂြိုၚ်စရဵု = ပျက်ရယ်ပြုသည်။ || ‘ပစရဵု’၊ ‘ပဂရိုၚ်စရဵု’၊ ‘ဂြိုၚ်စရဵု’ ရှု။')
,(3857,3,4,'(အနာ) ပုပ်ရောင်ရိရွဲသည်။','“ဥပ္ပရာဇာဂှ် က္တဵုဒှ်ယဲကုဋ္ဌတၞီ အလုံဇကုရ။ ပါ်ထကးဒှ်အာသရတုဲ သ္အုဲသရဵုအာ သီုဍာ်သရဇွောဝ်ဒၟံၚ်။” (ဇ—၅၁၉။ အစွောံ။) = “ဥပ္ပရာဇာသည် တစ်ကိုယ်လုံး နူနာရောဂါဖြစ်၏။ အနာသည် ကွဲပေါက်ပုပ်ရောင်ရိရွဲ၍ အနာရည်ယိုစီး လျက်ရှိ၏။”')
,(3859,3,4,'(ဦးခေါင်းတွင်)ပန်ဆင်သည်။','စရှ်ပ္ကဴ = ပန်းပန်သည်။')
,(3860,3,4,'၁။ သွန်ချသည်။ လောင်းချသည်။','“ဍာ်ဂှ် စရိုဟ်စုတ်ပ္ဍဲထးညိ။” = “ထိုရေကို ခွက်ထဲသို့ သွန်ချလိုက်ပါ။”')
,(3860,3,4,'၂။ (တင်းတိမ်၊ ကန့်လန့်ကာစသည်)ကာရံသည်။','စရိုဟ်ဇနိက် = တင်းတိမ်ဖြင့်ကာရံသည်။ || “ကြုက်ဂှ် မၞုံမြမောဝ်လောန် မၞုံရှ်သာလောန် သၟိၚ်ကဵုဒက်လဝ် ကၟာၚ်တုဲ ကဵုစရိုဟ်လဝ်ဓနိက်ရ။” = “ထိုသရက်သည် အလွန်မွှေးသောရနံ့ရှိ၏၊ အလွန်လျှင်အ ရသာရှိ၏၊ မင်းသည် ထိုသရက်ပင်ကို တံတိုင်းဆောက်လုပ်စေ၍ တင်းတိမ်ဖြင့် ကာရံထားစေ၏။”')
,(3861,3,4,'ရေစက်ချသည်။','စရိုဟ်ဍာ်ဇိုန်ပိုန် = ရေစက်ချအမျှပေးဝေသည်။')
,(3862,3,4,'အဘိသိက်သွန်းသည်။','“ပ္ဍဲလတူဗွဝ်ကြက်ရတ် ပ္တန်လဝ်ဗောဓိသတ်တုဲ စရိုဟ်ဍာ်ပသေက်ရ။” (ဇ—၄၄၅။ အစွောံ။) = “ဘုရားလောင်းအား ရတနာအစု­ထား၍ အဘိသိက်သွန်း၏။” || ‘စဝ်ဍာ်ပသေက်’ ဟုလည်းသုံးသည်။')
,(3863,3,1,'လိမ္မာပါးနပ်ခြင်း။ အလိမ္မာ။ အစွမ်းအစ။ ပါးရည်နပ်ရည်။','မၞုံကဵုစလဳစလး = အစွမ်းအစရှိသော။ || မဟၟဲကဵုစလဳစလး = အစွမ်းအစမရှိသော။ || အောန်ကဵုစလဳစလး = အစွမ်း အစနည်းပါးသော။ || “ယွံဒေံဗြဴ၊ နဥပ္ပာဲစလဳစလးအဲတုဲ အဲမဂွံ(ကကြၚ်ဝွံ)ရောၚ်ၝောံ၊ ၝောံစရ” ကၠဵုကၟက်ဂးကဵုကၠဵုဗြဴရ။ (ဇ—၄ဝဝ။ အစွောံ။) = “ရှင်မမြေခွေး၊ ငါ၏ဥပ္ပါယ်အလိမ္မာဖြင့် ဤငါးကြင်းကို ရခဲ့၏၊ ရှင်မ စားလော့” မြေခွေးဖိုဆို၏။ || “နအစောံစလဳစလးစၞာဲဗြဴဂှ် လှေအ်လှန် ကောန်အဲ ညံၚ်သ္ဂောံညိ” ဂးတုဲ သေဋ္ဌဳဗြဴဖအောဝ်ဏာ ဗြဴသရာဲဍုၚ်ဂှ်ရ။ (ဇ—၁၄။ အစွောံ။) = “ရှင်မ၊ သွားပါချေ။ မိန်းမအစွမ်းအလိမ္မာမာယာဖြင့် ငါ့သားကို ဆောင်ပါချေ” ဟု သူဌေးမက ပြည့်တန်ဆာမကို စေလိုက်၏။ || “ကဂမၠိုၚ်ပ္ဍဲလစဝွံ ဟိုတ်သ္ဒီုမအောန်စလဳစလး သီုဖအိုတ်ဒးလုပ် ဒကဴတဲပံက်ဟေၚ်။” (ဇ—၃၈။ အစွောံ။) = “အိုင်­နေသော ငါးအပေါင်းတို့သည် မိုက်မဲခြင်း အလိမ္မာနည်းခြင်းကြောင့် အားလုံးတို့သည် ဗျိုင်း၏လက်ခုပ်တွင်းသို့ ဝင်ရောက်ကြရကုန်၏။”')
,(3863,3,4,'လင်းလက်တောက်ပသည်။ ပြိုးပြိုးပြက်အရောင်ထွက်သည်။','“မၞိက်ရတ်မၞုံကဵုလျးစလဳစလး” = “ပြိုးပြိုးပြက်ထွက်သော အရောင်ရှိသော ပတ္တမြားရတနာ။”')
,(3864,3,1,'‘တလးစရာဲ’ (န)နှင့်အတူတူ။',NULL)
,(3864,3,4,'တင့်တယ်သည်။','“ဗောဓိသတ်ဒှ်စိၚ်ဗ္တာၚ် — ဂပ်ဂဝ်စလးစရာဲ ဂေါဝ်လောန်သန်ဟေၚ်။” (ဇ—၁၂၂။ အစွောံ။) = “ဘုရားလောင်းသည် ဆင်ဖြူဖြစ်၍ အလွန်လျှင်တင့်တယ်လှပ၏။”')
,(3865,3,4,'ခုန်သည်။','“(ဗောဓိသတ်သၟိၚ်ကၞုဲ) စလာ်အာနူသြၚ်လ္ပာ်ဏအ်တုဲ စိုပ်တၟံလးဒေါဝ်ဂှ်ရ။ နူတၟံလးဒေါဝ်ဂှ် စလာ်အာပၠန်တုဲ ဂွံစိုပ်တ္ကံမၞုံကဵုသစ္ဆုဂှ်ရောၚ်။” (ဇ—၅၇။ အစွောံ။) = “ဘုရားလောင်းမျောက်မင်းသည် ဤမှာဘက်ကမ်းမှ ခုန်၍ မြစ်လယ်ရှိကျောက်ဖျာ သို့ရောက်၏။ ထိုကျောက်ဖျာမှ ခုန်ပြန်၍ သစ်သီးရှိသောကျွန်းသို့ရောက်၏။”')
,(3866,3,4,'လှုပ်သည်။ ဗောင်ဗင်ခတ်သည်။',NULL)
,(3867,3,4,'တုန်လှုပ်သည်။ ချောက်ချားသည်။','ဓါတ်စလိုက်စလာဲ = (ခန္ဓအတွင်း­) ဓါတ်ချောက်ချားသည်။')
,(3868,3,1,'အမြှေး။','စၠာၚ်ဂြိုဟ် = အသည်း၏အမြှေး။')
,(3869,3,1,'အော်မြည်သည်။ တွန်မြည်သည်။','‘လလောၚ်စလာၚ်၊ စာၚ်ဍေဝ်မြာ်ထဝ်။’ (လိက်ပ္တံပါရမဳ။ အစွောံ။) = ‘တောကြက်၊ ရွှေဥဒေါင်းတို့သည် အော်မြည်တွန်ကျူးကုန်၏။’ || ‘တၟအ်မြ ပစလံၚ် လျိုၚ်ၜါပသာ။’ (ရာဇာဝံသသံခိပ်။ အစွောံ။) = ‘နှစ်ပိဿာအလေးချိန်ရှိသော မြကျောက်ကို စိန်ဖူးတော်လုပ်သည်။’')
,(3870,3,1,'၁။ (စေတီ၏)စိန်ဖူး။',NULL)
,(3870,3,1,'၂။ (ဥပစာ) အထွတ်အမြတ်။','“ကျာ်တြဲမစိုန်ဒှ်တဴ စလံၚ်ၝောအ်ကိုဋ်လိုက်။” = “လောက၏အထွတ်အမြတ် ဖြစ်တော်မူသောမြတ်စွာဘုရား။”')
,(3871,3,1,'အထွတ်အထိပ်။ အထွတ်အမြတ်။',NULL)
,(3872,3,1,'ချည်တိုင်။','စလိုၚ်စိၚ် = ဆင်ချည်တိုင်။ (ပါဠိ—အာလာန/ထမ္ဘ) || “ရဴဇၟူတမြအ် ကၠေၚ် မပကဝ်ကၠေံစလိုၚ်ဂှ်ကီု။” (ဇ—၅၁ဝ။ အစွောံ။) = “ဆင်ချည်တိုင်ကိုချိုးဖျက်သော အ မုန်ယစ်သောဆင်ပြောင်ကဲ့သို့။” (မြန်မာညောင်ကန်မူ­ ‘သံကြိုး’ ဟုဆိုသည်။)')
,(3873,3,4,'ဝတ်ဆင်သည်။ မွမ်းမံသည်။',NULL)
,(3874,3,1,'ၚုတ်ချွန်။ ငြောင့်။',NULL)
,(3875,3,1,'ဆူးငြောင့်။','“တရဴပၞာန်မဇက်အာဂှ် ညံၚ်ဟွံမွဲကဵုစလိုၚ်ဇလဂှ်ကီု သတးညံၚ်ဂတာတဲ ဂှ်ကီု ဣသိက္တဵုဗဒှ်တုဲ။” (ဇ—၅၃၂။ အစွောံ။) = “လမ်းခရီး­ ကြမ်းတမ်းကုန်သော ဆူးငြောင့် အစရှိကုန်သော ခပ်သိမ်းသောဘေးရန်တို့ကို ကွယ်စေ၏။” (ညောင်ကန်)')
,(3876,3,4,'ချောမွေ့သည်။',NULL)
,(3877,3,1,'နံ့သာ။',NULL)
,(3878,3,1,'အရသာ။','“(သၟိၚ်ခါမစဖျုန်ဂှ်) စလာဲရှ်သာလောန်နူဖျုန်ကၞုဲတုန် မဒှ်ပ္ဍဲပါၚ်သၟိၚ် သၟိၚ်ဒှ် အသၚ်ကာရ။” (သၠပတ်ဒ္ၚောဝ်သၜောံ) = “မင်းသည် ထိုအသားကို စားသည်ရှိသော် မျောက်သားထက် ထူးကဲသောအရသာသည် ခံတွင်း­တွေ့သဖြင့် မင်းသည် မယုံသၚ်္ကာဖြစ်၏။”')
,(3879,3,4,'ပေါက်ထွက်အောင်လုပ်သည်။ ဖောက်သည်။','“လ္ပကလိုဟ်ထောံ ထၟာဲတိ ဂှ်ညိ။” = “ထိုမြေအိုးကို မဖောက်လိုက်ပါနှင့်။” || ‘ကၠိုဟ်’ (ကြိ) လည်းရှု။')
,(3880,3,4,'တစ်ဖက်ကမ်းသို့ပို့သည်။','ကၠာဲစၠောအ်ဘာသာ = ဘာသာပြန်ဆိုသည်။ || ‘ကလောအ်’ ဟုလည်းရေးသည်။')
,(3881,3,1,'အမြှေး။',NULL)
,(3882,3,1,'အူများကိုဖုံးအုပ်ထားသောအမြှေး။',NULL)
,(3883,3,1,'ကျောက်ကပ်။',NULL)
,(3884,3,1,'ဒန်ပူစားသည်။ တံပူစားသည်။ သွားတိုက်သည်။ (ရှေးသုံး)',NULL)
,(3885,3,4,'တံစိုးလက်ဆောင်ယူသည်။ လာဘ်စားသည်။ တံစိုးစားသည်။','“သေနာပတိသၟိၚ်ဂှ်တုန် သ္ဂုတ်သၞောဝ်စၞာဲ စသဳဖဵုညးတုဲ သၞောဝ်ဇၞးဂှ် ကယကၠေံ၊ သၞောဝ်ကျဂှ် ဇၞးကၠေံဍေံပ၊ ဟွံဒှ်ဗဗွဲ ဓဝ်သက်က်ရ။” (ဇ—၂၂ဝ။ အစွောံ။) = “မင်း၏သေနာပတိသည် စဉ်းလဲစွာတရားဆုံးဖြတ်၏။ တံစိုးစား၍ နိုင်သောတရားကို ရှုံးစေ၍ ရှုံးသောတရားကို နိုင်စေ၏။ တရားသဖြင့်မဖြစ်။” || ‘သဳဖဵု’ (န) တွင်လည်းရှု။')
,(3886,3,4,'(ဒုက္ခ၊ သုခစသည်) ခံစားသည်။ စံစားသည်။','စသိုၚ်တသိုက်၊ ဂွံစသိုၚ်တသိုက် = သုခချမ်းသာကို ခံစားသည်၊ စံစားရသည်။ || စသိုၚ်ဒဒိုက်၊ ဒးစသိုၚ်ဒဒိုက် = ဒုက္ခဆင်းရဲကို ခံစားရသည်။ || “ဗြဴပန်ဂှ်စုတိတုဲ ဂွံတိုန်စိုပ်ဍုၚ်သွဝ် — ဂွံစသိုၚ်တဴတသိုက်ဒိပ်ရ။” (ဇ—၂၆၉။ အစွောံ။) = “ထိုမိန်းမလေးယောက်တို့သည် စုတေ၍ နတ်ပြည်­ဖြစ်၏။ နတ်စည်းစိမ်ကို စံစားကြရကုန်၏။” || “ပ္ဍဲဍုၚ်နရက်တေံ သတ်ရနက်တအ် ဒးစသိုၚ်ဒဒိုက် မဂိက္တာန်ရိၚ်ကတၚ်ရ။” = “ငရဲပြည်­ ငရဲသားများသည် နာကျင်ပူလောင်သော ဒုက္ခဆင်းရဲကို ခံစားကြရကုန်၏။” || “(တြုံ ကမၠတ်ဂှ် ညး)ပတိုန်ဆုစရံၚ် ဒုက္ခဝေဒနာဇၞော်ဟေၚ် မဒးစသိုၚ်တဴရ။” (ဇ—၁၄၇။ အစွောံ။) = “ထိုခိုးသူယောကျာ်းအား တံကျင်လျှိုကုန်၍ ထိုခိုးသူသည် ကြီးစွာသောဒုက္ခဝေဒနာကို ခံစားရ၏။”')
,(3887,3,4,'စားသည်။ စားသောက်သည်။','“စဟာပ်တုဲ — လးကဵုထကဝ် လးယာတ်တုဲ ကဵု သ္တိက်ရ။” (ဇ—၃ဝ၂။ အစွောံ။) = “(ထမင်းဟင်း) စားသောက်ပြီးနောက် ဖျာကို၄င်း အဝတ်ကို၄င်း ခင်းပေးပြီးလျှင် အိပ်စေ၏။”')
,(3888,3,1,'ချွန်း။ ချွန်းတောင်း။ ဆင်ချွန်း။','‘ခၜံက်’ ဟုလည်းရေးသည်။ (ပါဠိ— အကုၚ်္သ)')
,(3888,3,4,'(ပေါက်တူး၊ ချွန်းစသည်ဖြင့်) ပေါက်သည်။','“ကၞုဟ်ဂှ် မဒးစၜံက်ကဵုလၟာန်တုဲ သဏှံက်ပါ်အာ မဒးချိုတ်အာရ။” (ဇ—၁၇၈။ အစွောံ။) = “ထိုလိပ်သည် အိုးထိန်းသည်က ပေါက်တူးဖြင့် ပေါက်သည်ကိုခံရပြီး သေရလေ၏။”')
,(3889,3,1,'တောအုပ်။ တောအုပ်၏အဝ။','“နူကွာန်ဂှ်အာတုဲ ဒးစ္ၜုဲဂြိုပ်ဇၞော်ပၠန်ရ။ ပ္ဍဲ စ္ၜုဲဂြိုပ်ဂှ် ဒမၠမသုန်စှ်ောနွံ။” (ဇ—၃၇၄။ အစွောံ။) = “ထိုရွာမှသွား၍ တောအုပ်ကြီးသို့ ရောက်၏။ ထိုတောအုပ်­ ငါးကျိပ်ကုန်သော ခိုးသူတို့သည်ရှိကုန်၏။” || “ပ္ဍဲအကြာမဂဓရးကဵုအၚ်္ဂရး ကာသိကရးတံဂှ် စ္ၜုဲမုဟ်ဂြိုပ်မဂပ်ဂဝ်လှိၚ်စိုတ်ဂှ်နွံ။” (ဇ—၄၉ဝ။ အစွောံ။) = “အၚ်္ဂတိုင်း၊ မဂဓတိုင်း၊ ကာသိတိုင်းဟူသော တိုင်းသုံးတိုင်းတို့၏အကြား­ မွေ့လျော်ဘွယ်ရှိသော တောအုပ်သည် ရှိ၏။” (ညောင်ကန်) || ‘စရုဲမုဟ်ဂြိုပ်’ လည်းရှု။')
,(3890,3,4,'သန့်ရှင်းစင်ကြယ်အောင်လုပ်သည်။ သန့်စင်သည်။ သုတ်သင်သည်။ ရှင်းလင်းသည်။','“ဣသိဂိုၚ်စအးကဏေအ်အသုဘတံဂှ်တုဲ တုက်ဍာ်ကြဴကြာတ်စအးကၠေံရ။” (ဇ—၆၆။ အစွောံ။) = “ရသေ့သည် မစင်တို့ကို သုတ်သင်ရှင်းလင်း၍ ရေခပ်ပြီးလျှင် ဆေးကြောသုတ်သင်၏။” “ယွံဥပါလိထေရ်၊ ခမဳဗြဴသၟတ်ဝွံဂှ် ပ္ဍဲဒေါဝ်ပုရိသာတ်ပန် မၞးစဳစတ်စအးကၠေံဒုဟ်ဍေံညိကၠာ” ကျာ်တြဲဂး။ (ဇ—၁၂။ အစွောံ။) = “ဥပါလိ၊ သင်သည် လေးပါးသောပရိသတ်အလယ်­ ဤရဟန်းမိန်းမငယ်၏အမှုကို သုတ်သင်လော။” || “ဒၞာဲဋ္ဌာန်မဟွံဂွံသ္အးတံဂှ် တွံဇအးရ။” (ဇ—၃ဝ၁။ အစွောံ။) = “မသန့်ရှင်းသောအရပ်တို့ကို တံမြက်လှည်း၍ သန့်ရှင်းစင်ကြယ်အောင်ပြု၏။” || ‘သ္အး’ လည်းရှု။')
,(3891,3,4,'၁။ စက်ဆုပ်ရွံရှာသည်။ ရွံမုန်းသည်။','“ဟာဲကၠိက်အယုတ်၊ သော်ဇကုဗှ်ေ မလေတ်တဴကေုာံသ္ၚိဍာ်ပဿဴ ဂပ်ဂဝ်က္ဍုဟ်ရောၚ်။ အမြာဲမသဇကုဗှ်ေဂှ် ပ္ဍးထီုဒၟံၚ် ဂပ်ဂဝ်စအိုတ်စိုတ်ရောၚ်” ဇာဒိသိုၚ်ဂး။ (ဇ—၁၅၃။ အစွောံ။) = “အချင်းဝက်ပုပ်၊ သင်သည် မစင်လူးခြင်းကြောင့် ပုပ်သောအမွေးရှိသည်ဖြစ်၏။ အလိုမရှိအပ် စက်ဆုပ်ရွံရှာအပ်သော အနံ့ရှိသည်ဖြစ်၍ ပုပ်နံ့နံ၏” ဟုခြင်္သေ့ဆို၏။ (ညောင်ကန်) || “တြုံပိုတ်ဇိုၚ်တဲကတောဝ်မုဟ် မဂပ်ဂဝ် က္ဍုဟ်စအိုတ်တဴစိုတ်ဝွံ မူပလွဳပရာဝေၚ်ဍေံရော။” (ဇ—၁၉၃။ အစွောံ။) = “စက်ဆုပ်ရွံရှာဖွယ်ကောင်းသော ခြေလက်နားနှာခေါင်းပြတ်သော ဤယောကျာ်းကို အဘယ်ကြောင့် ကုသနေရပါ သနည်း။” || “ပ္ဍဲကာလဍာ်တက်မဇွောဝ်ပေၚ်အာ အလုံက္ဍိုပ်သၟိၚ် အလုံဇကုသၟိၚ်တုဲ သၟိၚ်က္ဍုဟ်စ အိုတ်စိုတ်တုဲ—။” (ဇ—၂ဝ၂။ အစွောံ။) = “မင်း၏ဦးခေါင်းအလုံး ကိုယ်အလုံးကို ရက်တက် ရည်ယိုစီးသည်ရှိသော် မင်းသည် စက်ဆုပ်ရွံရှာ၏။” || “(သၟိၚ်ဒဇန်သဟာသဳဂှ်) ညးက္ဍုဟ်မၠေံ စအိုတ်တဴစိုတ် ဟွံဒးဂၞပ်ပူမှ် ရဴလမၠံမတဴပ္ဍဲမတ်ကီု စိုတ်ညးဂမၠိုၚ်မဒှ်—။” (ဇ—၂၄ဝ။ အစွောံ။) = “ရက်စက်ကြမ်းကြုတ်သော ထိုမင်းကို လူတို့သည် စက်ဆုပ်ရွံရှာမုန်းတီးကြကုန်၏။ လူများမ နှစ်သက်ကုန်။ လူများ၏စိတ်ဝယ် မျက်စိ­ကျသောမြူကဲ့သို့ဖြစ်၏။” || “ကောန်သေဋ္ဌဳဂှ် က္ဍုဟ် ဇအိုတ်စိုတ်ကဵုဗြဴတုဲ ဂွံသံၚ်ဝေဂရ။ (ဇ—၄၂၅။ အစွောံ။) = “သူဌေးသားသည် မိန်းမကို စက် ဆုပ်ရွံရှာ၍ သံဝေဂရ၏။”')
,(3891,3,4,'၂။ စိတ်ကုန်သည်။ စိတ်ပင်ပန်းသည်။ မပျော်မွေ့ငြီးငွေ့သည်။','“ပ္ဍဲဥဒျာန်ဂှ် ပံက်မွဲနွံ။ ပံက်ဂှ် တၞဟ်နဂ္ၚေၚ်ဂၠာဲစဂှ် ဟွံသၟဟ်ရထတုဲ ဇအိုတ်စိုတ်တုဲ မဂၠာဲဟီုဗြုရောၚ်။” (ဇ—၄၁၈။ အစွောံ။) = “ထိုဥယျာဉ်­ တစ်ခုသောဗျိုင်းသည်ရှိ၏။ ထိုဗျိုင်းသည် အစာရှာစားအံ့သောငှာ မတတ်နိုင်သည်ဖြစ်၍ စိတ်ပင်ပန်းငြီးငွေ့၍ အော်မြည်၏။”')
,(3891,3,1,'စိတ်ပင်ပန်းခြင်း။ ငြီးငွေ့မမွေ့ပျော်ခြင်း။','“ယဝ်ရမရာတ် သၟိက်ဂွံဗလးဇအိုတ်စိုတ်ပံက်ဂှ်မ္ဂး ဗပေၚ်ကဵုဍာ် လစဂှ်ညိရ။” (ဇ—၄၁၈။ အစွောံ။) = “အရှင်မင်းကြီးသည် ထိုဗျိုင်း၏ငြီးငွေ့မမွေ့ပျော်ခြင်းကို အကယ်၍ လွှတ်လိုသည်ဖြစ်ငြားအံ့၊ ထိုရေကန်ကို ရေဖြည့်ပေးပါလော့။”')
,(3892,3,4,'အီသည်။ မုန်းသည်။','‘ဇအိုန်’ ရှု။')
,(3893,3,4,'မုန်းသည်။ စက်ဆုပ်သည်။ ရွံရှာသည်။','‘ဇအိုန်စိုတ်’ ရှု။')
,(3894,3,1,'အန်ခြင်း။ အန်ဖတ်။',NULL)
,(3894,3,4,'အန်သည်။','“(ဗမၞးဂှ်) ပုၚ်သီုကဵုဆီဂှ် စအအ် တိတ်အာရ။” (ဇ—၁၇၉။ အစွောံ။) = “ထိုပုဏ္ဏားသည် သွေးနှင့်တကွသောထမင်းကို အန်၏။” || ‘ထအအ်’ ဟုလည်းရေးသည်။')
,(3895,3,1,'ငါးကြီးအန်ဖတ်။',NULL)
,(3896,3,1,'အခြၚ်။ အိမ်အမိုးအောက်ခံဝါးတန်း။',NULL)
,(3897,3,4,'(ဓါးဖြင့်)ခွဲသည်။ လှီးသည်။ (ပါဠိ—ဆိန္ဒတိ)','“ကၠိက်ၜါလပါ်ဂှ် ဗျာံလဝ်ဂၞေဟ်တုဲ (တုက် ကၠဂှ်) ဂၞဴကၠညံၚ်ညးစာကၠေံ ကဵုၜုန်ဇမ္ကေက်ရ။” (ဇ—၂၈၃။ အစွောံ။) = “နှစ်ဖက်မှဝက်တို့သည် အစွယ်တို့ဖြင့် ချိန်ရွယ်ထားပြီးလျှင် ကျားကိုထိုးခတ်သည်ရှိသော ကျား၏ဝမ်းသည် ချွန်ထက်သောဓါးဖြင့် လှီးခွဲဘိသကဲ့သို့ဖြစ်၏။”')
,(3898,3,4,'ကြောက်ရွံ့စေသည်။ ခြောက်သည်။','“ဋ္ဌာန်ဂှ် စိၚ်ဒမြိုဟ်နွံ၊ ဋ္ဌာန်ဂှ် ချေံဒမြိုဟ်နွံ၊ ဋ္ဌာန်ဂှ် ဗ္ၜေံဒမြိုဟ်နွံ” သာ်ဝွံဂးတုဲ ခမဳဗြဴဂှ် ဟီုစာကမၠတဴညး(ဂမၠိုၚ်ရ)။ (ဇ—၁၁၅။ အစွောံ။) = “ထိုအရပ်­ ကြမ်းသောဆင်ရှိ၏၊ ထိုအရပ်­ ကြမ်းသောမြင်းရှိ၏၊ ထိုအရပ်­ ကြမ်းသောဆိတ်ရှိ၏” ဟုဆိုကာ ထိုရဟန်းမိန်းမသည် အခြားသူတို့အား ကြောက်ရွံ့အောင်ပြော၏။')
,(3899,3,10,'(န) ပေးကမ်းခြင်း။ စွန့်ကြဲခြင်း။ စာဂတရား။ (= ပွသလးပွး။ တွဵုတွေတ်။)','စာဂဇၞော်မသုန် = စွန့်ခြင်းကြီးငါးမျိုး။ (ဘုရားဖြစ်ရန် ဘုရားလောင်းတို့၏ သားသမီးဇနီးမယားအပါအဝင် စွန့်နိုင်ခဲသော စွန့်ကြဲခြင်းငါးပါး။)')
,(3900,3,11,'(န) အာရှအလယ်ပိုင်း ကုန်းမြင့်ဒေသတွင်တွေ့ရသော ဝန်တၚ်နို့စား မွေးရှည် နွား။ တိဗက်နွား။ စာမရီ။',NULL)
,(3901,3,1,'အကျင့်စာရိတ္တ။',NULL)
,(3902,3,1,'အကြီးအကဲ။ အကြီးအမှူး။','“(ကုပြောဟိတ်တရေံဂှ်) သၟိၚ်ပပူဇဴသကာ ဗွဲမဂၠိုၚ်ရ။ ကၠေဝ်မက်စာသံက်တရေံ သၟိၚ်မဇိုန်ကဵုပၠန်ရ။” (သၠပတ်ဒ္ၚောဝ်သၜောံ)= “ထိုပုရောဟိတ်ဟောင်းအား မင်းသည် များစွာပူဇော်သက္ကာရပြု၏။ အကြီးအမှူးရာထူးဟောင်းတို့ကို ဆောက်နှင်းပေး အပ်ပြန်၏။”')
,(3903,3,9,'ကြိယာကို လေးနက်စေသောစကားလုံး။ အမှန်။ စင်စစ်။',NULL)
,(3904,3,4,'၁။ စီချယ်သည်။ အလှဆင်သည်။','“ၝောအ်ကိုဋ်ဝွံ စိစောန်တဴနကဵုမၞိက်ဗိုတ်ဗၠဲရ။” = “ဤမကိုဋ်သည် ကျောက်တံပတ္တမြားတို့ဖြင့် စီချယ်ထားသည်။” || “စိၚ်မ္ၚဵုသၟိၚ်ဂှ် ညးဂြောပ် စိစောန်လဝ် နကဵုဇာထဝ်ရ။” = “မၚ်္ဂလာဆင်တော်ကို ရွှေကွန်ယက်ဖြင့်ဖုံးလွှမ်း၍ အလှဆင် ထားသည်။”')
,(3904,3,4,'၂။ (အသံ၊ စကားစသည်) သာယာနာပျော်ဖွယ်ဖြစ်သည်။','“ကုမာရကဿပထေရ်ဝွံ ဆိုက်ဗ္ဒက်ပ္ဍဲအဘိဓဝ်တုဲ မၞုံရမျှာၚ်မစိစောန်လောန် ဂွံဒှ်ဓမ္မကထိုက်မပြဲရ။” = “ကုမာရ ကဿပမထေရ်သည် အဘိဓမ္မာကျမ်းကိုတတ်၍ ဆန်းကြယ်စွာ တရားဟောတတ်သော မြတ်သောဓမ္မကထိကပုဂ္ဂိုလ်ဖြစ်၏။”')
,(3904,3,3,'ဆန်းကြယ်သော။','ဇနိက်ကသူမစိစောန် = ဆန်းကြယ်စွာသော ပန်းချီကားပါသော ကန့်လန့်ကာ။ || ပၞိက်ထဝ်မစိစောန် = ဆန်းကြယ်သောရွှေ ယပ်တောင်။ || “မြာ်ကၟက်ဂှ် မၞုံကဵုအရံၚ်သာ်မစိစောန်ရ။” = “ထိုဥဒေါင်းဖိုသည် ဆန်းကြယ်စွာသော အရောင်အဆင်းရှိ၏။” || “ညံၚ်ရဴဒြုန်ကမုမစိစောန် မပေၚ်ဒၟံၚ်နအသုဘ။” (ဇ—၁၃၈။ အစွောံ။) = “မစင်တို့ဖြင့်ပြည့်နေသော ဆန်းကြယ်လှပသော ဖြူသောပိုးခြကဲ့သို့။” || “ဝုတ်ဒိုဟ်ဂှ် ဇနိက်မစိစောန် ကဵုစဵုဗိုၚ်လဝ်—။” (ဇ—၂၅၄။ အစွောံ။) = “ထက်ဝန်းကျင်မှ ဆန်းကြယ်သော တင်းတိမ်ဖြင့် ကာရံ၏။” (ညောင်ကန်)')
,(3905,3,4,'ပြည့်စုံသည်။ ပြည့်စုံစေသည်။ ပြည့်စုံအောင်ပြင်ဆင်သည်။','“ဂတာံဝွံ ဟိုတ်မ ညာတ်ဂၠိၚ် ပယောဂဒွး — မသ္ဂောံလနိန်ဗပိန်သတြု စိစုမ်ဗ္ဂပ်ပြာပ်လဝ်ဒးတုဲ (ၜိုန်ပံက်စၞာဲဟီုဘ ကမၠကီုလေဝ် ဟွံဖေက်ရ။)” (ဇ—၃၈။ အစွောံ။) = “ဗုဇွန်သည် အရှည်ကိုမြင်သဖြင့် ရန်သူကို အောင်မြင်နိုင်ကြောင်း မှန်ကန်ကောင်းသော အားထုတ်မှုကို ပြည့်စုံအောင် ပြင်ဆင်ထားပြီးဖြစ်သ ဖြင့် ဗျိုင်းစဉ်းလဲက ပြောဆိုခြိမ်းခြောက်သော်လည်း မကြောက်။”')
,(3906,3,4,'၁။ ပြည့်စုံသည်။ ပြည့်စုံအောင်ပြင်ဆင်သည်။','“သွက်ပလိုက်လေဝ် သုစရိုတ်အ သဝ် ဆန်ၜန်စိစီုဂလိုၚ်လဝ်—။” (ဇ—၃၈။ အစွောံ။) = “တမလွန်အတွက်ကိုလည်း ကောင်း မြတ်သောသုစရိုက်ကို ပြည့်စုံအောင် စီမံပြင်ဆင်ပွားများထားပါ။” || ‘စိစုံ’ (ကြိ) နှင့်အတူတူ။')
,(3906,3,4,'၂။ လျဉ်းပါးသည်။ ဒွိဟဖြစ်သည်။ အနက်မပြတ်သားဖြစ်သည်။',NULL)
,(3907,3,11,'(န) တိစီဝရိတ်။ သၚ်္ကန်းသုံးထည်။',NULL)
,(3908,3,4,'၁။ မီးပြသည်။ အလင်းရောင်ပေးသည်။','စဳကဵုပၟတ်ဓါတ် = လက်နှိပ်ဓါတ်မီးဖြင့် မီးထိုးသည်၊ အလင်းရောင်ပြသည်။ || “မၞိဟ်တၠဒြပ်တံဂှ် ဍေံရပ်ကေတ်မိန်ရှောတဴၜံၚ်တုဲ ဍေံစဳဗက်ကၠုၚ် လၟာ်ဇိုၚ်ကမၠတ်ဂှ် ကၠုၚ်စိုပ်ရ။” (ဇ—၃၁၁။ အစွောံ။) = “ဥစ္စာပိုင်ရှင်တို့သည် မီးရှူးကိုကိုၚ်ကုန် ၍ အလင်းရောင်ပြု၍ ခိုးသူ၏ခြေရာစဉ်ကိုလိုက်၍ ရောက်လာကြကုန်၏။”')
,(3908,3,4,'၂။ (ကျောက်မျက် တို့ကို) စီခြယ်သည်။','“ကၟက်ကအ်ဂှ် စဳလဝ်ကဵုမတ်မၞိက်ရ။” = “ထိုလည်ဆွဲကို ပတ္တမြားဖြင့် စီခြယ်ထားသည်။”')
,(3909,3,4,'သိလိမ္မာသည်။ ပါးနပ်သည်။','“ကောန်အဲဍောတ်ဒၟံၚ်ဏီ၊ ဟွံစိုပ်အဝဲမစဳကၠးဏီ။” = “ငါ့သားသည် ငယ်သေးသည်၊ တတ်သိလိမ္မာသောအရွယ်သို့ မရောက်သေး။” || “ဗောဓိသတ် အာစိုပ်ဒဒှ်မစဳကၠးတုဲ—။” (ဇ—၉၆။ အစွောံ။) = “ဘုရားလောင်းသည် သိလိမ္မာသောအဖြစ်သို့ ရောက်၍—။” || “ပသာ်အဲသ္ပကဵုမၚ်ဗၠာဲဝွံ သ္ဂောံစဳကၠးညိရော။” (ဇ—၁၂၃။ အစွောံ။) = “ဤလု လင်သိလိမ္မာလာအောင် အဘယ်သို့ငါပြုရအံ့နည်း။” || “ယွံဒေံ၊ မဟွံစဳကၠးဏီ။” (ဇ—၁၄၅။ အစွောံ။) = “ညီထွေး၊ သင်သည် မလိမ္မာသေး။” || “မၞုံကဵုကသပ်ဂၞန်ပညာမစဳကၠး—။” (ဇ—၂၇ဝ။ အစွောံ။) = “သိလိမ္မာသော အတွေးအခေါ်ဉာဏ်ပညာရှိသော—။” || “(အမာတ်ဂှ်) နွံကဵုပညာ သကာလောန် စဳကၠးလောန် ဆိုက်ဗ္ဒက်ပ္ဍဲဥပ္ပါယ်လောန်။” (ဇ—၃ဝ၁။ အစွောံ။) = “အမတ်သည် ပညာရှိ၏၊ လိမ္မာ၏၊ အကြောင်းဥပါယ်ကို သိ၏။” (ညောင်ကန်)')
,(3910,3,4,'‘သဳခေန်’ ရှု။',NULL)
,(3911,3,4,'ပြိုးပြိုးပြက်ပြက်လက်သည်။',NULL)
,(3912,3,4,'ရှင်းလင်းသည်။ ထင်ရှားသည်။ ပေါ်လွင်သည်။',NULL)
,(3913,3,4,'သုတ်သင်သည်။ စစ်ဆေးသည်။ စိစစ်သည်။ စုံစမ်းသည်။','“သဘဴသၟိၚ်မ္ဂးဂှ် အမှုဇၞော်ကီု သွတ်ကီု မက္တဵုဒှ်ဂှ် ဂၠာဲဂၠိုက်သၟာန်စဳစတ်စမတ်ကဵုဗိုန် ဂွံတီအိုတ်သ္အးတုဲ မဂပ်ဂဝ်ပ ကီုဒဏ်ရောၚ်သွံအဴ။” (ဇ—၄၇၂။ အစွောံ။) = “မင်းတို့မည်သည်ကား ဖြစ်ပေါ်လာသော ငယ်ငယ်ကြီးကြီးသော အမှုတို့ကို မြဲစွာစုံစမ်းစစ်ဆေး၍ အလုံးစုံကို သိရပြီးမှသာလျှင် မင်းဒဏ်ကိုပြု သင့်၏။” || “ယွံမရှာတ်၊ မၞိက်ကၠေံအာဂးဟာ” ထေအနန်သၟာန်။ “ယွံအဴ၊ အလုံနန်ဝွံဂၠာဲစဳစောတ်လေဝ် ကေတ်ဟွံဂွံရအဴ” သၟိၚ်ဂး။ (ဇ—၉၂။ အစွောံ။) = “မြတ်သောမင်းကြီး၊ ပတ္တမြားပျောက် သွားသည် ဆိုသလော။” “မှန်ပေ၏။ အလုံးစုံသောနန်းတွင်း­ စစ်ဆေးရှာသော်လည်းမရ။” || “ယွံဥပါလိထေရ်၊ ခမဳဗြဴသၟတ်ဝွံဂှ် ပ္ဍဲဒေါဝ်ပုရိသာတ်ပန် မၞးစဳစတ်စအးကၠေံဒုဟ်ဍေံညိကၠာ” ကျာ်တြဲဂး။ (ဇ—၁၂။ အစွောံ။) = “ဥပါလိ၊ သင်သည် လေးပါးသော ပရိသတ်အလယ်­ ဤရဟန်းမိန်းမငယ်၏အမှုကို သုတ်သင်လော။”')
,(3914,3,4,'စီစဉ်သည်။ စီကုံးသည်။',NULL)
,(3915,3,4,'ရှင်းပြသည်။ နားလည်အောင်သင်ပြသည်။','“ကောန်တအ်ဂွံတီမုတ်ဒွး မိမတအ်ဒးစဳပျး ကဵုရောၚ်။” = “သားသမီးများ အမှားအမှန်ကို ဝေဖန်ပိုင်းခြားတတ်ရန် မိဘများက ရှင်းလင်းသင်ပြရပါမည်။”')
,(3916,3,4,'အရောင်ဆိုးသည်။','“(ဗောဓိသတ်ဒှ်စိၚ်ဗ္တာၚ်) ဇိုၚ်ပန်(ညံၚ်)စဳဖျောန်သနောဟ်လဝ် နဍာ်ကြိုတ်ကီု။” (ဇ—၇၂။ အစွောံ။) = “ဘုရားလောင်းသည် ဆင်ဖြူဖြစ်၍ အခြေလေးချောင်း တို့သည် ချိပ်ရည်ဖြင့် ဆိုးထားဘိသကဲ့သို့ဖြစ်၏။”')
,(3917,3,4,'၁။ စီရင်သည်။ အဆင်သင့်ဖြစ်အောင် ပြင်ဆင်သည်။','“တ္ၚဲယးတေံ သ္ဂောံဖါပ်သၚ် ဒးစဳရေၚ်လဝ်နူတ္ၚဲဏအ်ရ။” = “မနက်ဖြန် သံဃာများအား ဆွမ်းကျွေးရန် ယနေ့ကတည်းက ပြင်ဆင်စီစဉ်ထားရမည်။” || “ဂွံတီကေတ်သၟိၚ်ဗာရာဏသဳစုတိအာတုဲ သၟိၚ်ကောသလရးဂှ် စဳရေၚ် ဗဵုပၞာန်မဂၠိုၚ် ဇက်ကၠုၚ်ဗိုၚ်လဝ် ဍုၚ်ဗာရာဏသဳရ။” = “ဗာရာဏသီမင်း နတ်ရွာစံသည့်သတင်းကို ကြားရသည်နှင့် ကောသလမင်းသည် စစ်ကိုပြင်ဆင်၍ အလုံးအရင်းနှင့် ချီတက်လာကာ ဗာရာဏသီမြို့ကို ဝန်းရံထား၏။” || “ယွံမိ၊ ယာံမိဂွံစဳရေၚ်တုဲဂှ် ဟွံစိုပ်ဒတုဲဟွံမွဲရ၊ မိဂွံစဳရေၚ်တုဲ စိုပ်ဒတုဲရမိ။” (ဇ—၁၂၆။ အစွောံ။) = “မိခင်၊ မိခင်စီရင်အပ်သောကိစ္စမည်သည် မပြီးမြောက်သည်ဟူ၍ မရှိပါ။ မိခင်စီရင်ရလျှင် အောင်မြင်ပြီးမြောက်ရမည်သာတည်း။”')
,(3917,3,4,'၂။ ထိမ်းမြားပေးသည်။','“ကောန်သဟာဲအဲ စဳရေၚ်ကဵုကောန်အဲဝွံတုဲ ဂိုၚ်လဝ်ကဵုဒၟံၚ်အာဖဴဂှ်ရ။” (ဇ—၁၂၅။ အစွောံ။) = “အဆွေ၏သမီးကို ငါ၏သားနှင့်ထိမ်းမြားပေးပြီးလျှင် အဆွေတို့နှင့်အတူ နေပါစေလော့။”')
,(3918,3,4,'အမှုစီရင်သည်၊ အမှုဆုံးဖြတ်သည်၊ နှစ်ဖက်သောအငြင်းအခုံကို အနိုင်အရှုံး စီရင်ဆုံးဖြတ်ပေးသည်။','“ဗောဓိသတ်ဒှ်အမာတ် စဳရေၚ်တဴဂဗုတ်ညးအိုတ်သီုရ။” = “ဘုရားလောင်းသည် မင်း၏အမတ်ဖြစ်၍ အလုံးစုံသောအမှုတို့ကို စီရင်ဆုံးဖြတ်ရ၏။”')
,(3919,3,4,'တရားစီရေၚ်သည်။ တရားဆုံးဖြတ်သည်။ အမှုစီရင်ဆုံး ဖြတ်သည်။','“ယြဴနာဲဗစာမွဲ စဳရေၚ်သၞောဝ် ဒးကဵုဒှ်ဗဗွဲဓဝ်ရောၚ်။” = “တရားသူကြီးမည်သည် တရားစီရင်ရာ­ တရားသဖြင့်ဖြစ်စေရမည်။” || “(သၟတ်ကောန်သၟိၚ်ဂှ်) အမာတ်ဂမၠိုၚ် ကဵုစဳရေၚ်ဂ ဗုတ်အမှုမွဲရ။” (ဇ—၂၄၇။ အစွောံ။) = “ထိုမင်းသားငယ်အား အမတ်တို့သည် အမှုတစ်ခုကို စီရင်ဆုံးဖြတ်စေ၏။” || “ဗောဓိသတ်ဒှ်အမာတ် စဳရေၚ်တဴဂဗုတ်ညးအိုတ်သီုရ။” (ဇ—၁၅၈။ အစွောံ။) = “ဘုရားလောင်းသည် အမတ်ဖြစ်၍ အလုံးစုံသောအမှုတို့ကို စီရင်၏။” || “သၟိၚ်တံ တမၠာတမၠာတေံဂှ် စဳစတ်ဇအးတုဲ မဂပ်ဂဝ်စဳရေၚ်အမှုညးရောၚ်။ ဟွံစဳစတ်ဇအးတုဲ စဳရေၚ်အမှုညးဂှ် ဟွံထေက်ညိအဴ။” (ဇ—၃၃၂။ အစွောံ။) = “ရှေးရှေးမင်းတို့သည် စိစစ်သုတ်သင်၍ အမှုကို စီရင်ကုန်၏။ မစိစစ်မသုတ်သင်ဘဲ အမှုကိုစီရင်ခြင်းသည် မလျောက်ပတ်။”')
,(3920,3,10,'(န) သၚ်္ကန်း။',NULL)
,(3921,3,10,'(ကြိ) သေသည်။ ကွယ်လွန်သည်။ စုတေသည်။',NULL)
,(3922,3,1,'(စုတိ = သေခြင်း။/ ပါတ် = ?။/ ဘၚ် = ပျက်စီးခြင်း။)','“သတ္တံ ဂမၠိုၚ်ဝွံ နွံတဴကဵုစုတိပါတ်ဘၚ်ရောၚ်။ မဒးဒှ်စၟိန်ပြမာန်သၟိၚ်ဂစိုတ်ဖအိုတ်ရ မရှာတ်။” (ဇ—၁၅၉။ အစွောံ။)')
,(3923,3,10,'(န) မေးမြန်းစစ်ဆေးခြင်းခံရသူ။ စွပ်စွဲပြစ်တၚ်ခြင်းခံရသူ။ စုဒိတက။','‘စောဒက’ လည်းရှု။')
,(3924,3,4,'၁။ စူးနှင့်ထိုးဖောက်သည်။',NULL)
,(3924,3,4,'၂။ မတ်စောက်သည်။','“ကၟဳဏအ်စူလောန်အာရ။” = “ဤအမိုးသည် အလွန်မတ်စောက်သွားသည်။”')
,(3924,3,4,'၃။ တည့်မတ်စွာတည်သည်။ ထောင်လျက် ထည်သည်။','တ္ၚဲစူ = နေမွန်းတည့်သည်။')
,(3925,3,10,'(န) ဘုရားလောင်း သိဒ္ဓတ္ထမင်းသား၏ဆံတော်ကို ဋ္ဌာပနာ၍ တာဝင်္တံသာတွင် တည်ထားသောစေတီ။ စူဠာမဏိစေတီ။',NULL)
,(3926,3,10,'(န) ၁။ စေတနာ။ စေ့ဆော်တိုက်တွန်းတတ်သောတရား။',NULL)
,(3926,3,10,'(န) ၂။ စေတနာ။ သူတစ် ပါးအကျိုးကို လိုလားသောသဘောထား။',NULL)
,(3927,3,10,'(န) စိတ်ဆင်းရဲမှု။ စေတသိကဒုက္ခ။',NULL)
,(3928,3,11,'(န) (လိုချင်ခြင်း၊ အမျက်ထွက်ခြင်း၊ မသိခြင်း စသည်ကဲ့သို့သော) စိတ်­ယှဉ်သောသဘော။ စေတသိက်။',NULL)
,(3929,3,11,'(န) စေတီ။',NULL)
,(3930,3,1,'စေတီကြီးကိုဝန်းရံ၍ တည်ထားသောစေတီငယ်။ စေတီရံ။',NULL)
,(3931,3,1,'၁။ သန်း။','ၚဳစဲ = သန်းရှာသည်။')
,(3931,3,1,'၂။ (သသက်) တံခူးလ။',NULL)
,(3931,3,4,'လှန်းသည်။','စဲတ္ၚဲ = နေလှန်းသည်။ || စဲဇကှ် = ခြောက်အောင်လှန်းသည်။')
,(3932,3,10,'(န) ၁။ ဆင်ခြေဆင်လက်။','အရေဝ်စောဒက = ဆင်ခြေဆင်လက်စကား။')
,(3932,3,10,'(န) ၂။ အပြစ်တင်ဆိုချက်။',NULL)
,(3932,3,10,'(န) ၃။ မေးမြန်းစိစစ် အပြစ်တင်ဆိုသောသူ။',NULL)
,(3933,3,4,'သူတစ်ပါးအကြောင်း မကောင်းပြောသည်။',NULL)
,(3933,3,1,'အပြစ်တင်သောစကား။',NULL)
,(3934,3,10,'(န) သူခိုး။ ခိုးသား။',NULL)
,(3935,3,10,'(န) မကိုဋ်ကျောက်။','မၞိက်စောလာမူဏိ = ပတ္တမြားဥသျှောင်ကျင်။ (ရှေးဘုရင်တို့၏ အသုံးအဆောင်။)')
,(3936,3,1,'မြေး။','ကောန်စဴ = မြေး။')
,(3936,3,4,'ပြန်သည်။','စဴစိုပ်သ္ၚိ = အိမ်ပြန်ရောက်သည်။')
,(3936,3,9,'ကြိယာကိုထောက်ပံ့ပေးသော စကားလုံး။','“ဇကုချပ်ပၠေၚ်ညး ညးဟွံလေၚ် ဇကုဟေၚ် စဴဒှ်လေၚ်ပၠန်။” = “သူတစ်ပါးကို မိမိမကောင်းကြံ၍ သူတစ်ပါးမပျက်စီးဘဲ မိမိသာလျှင် ပျက်စီးခြင်းသို့ ရောက်၏။”')
,(3937,3,4,'အကြံပြီးမြောက်သည်။','“ယွံဂစေံပံက်၊ မူကသပ်မွဲ ချပ်ဟွံစဴစိုတ်တုဲ မစံၚ်တူမဒေၚ်ဒၟံၚ်ဂှ်ရော” ကဂမၠိုၚ်သၟာန်။ = “ဥဗျိုင်းငှက်၊ ဘာကိုကြံစည်၍ အကြံမပြီးမြောက်၍ငေးမှိုင်နေပါသနည်း” ဟုငါးများမေး၏။')
,(3938,3,1,'ရှမ်းစော်ဘွား။',NULL)
,(3939,3,4,'ကွယ်လွန်သည်။ ဘဝတစ်ပါးသို့လားသည်။ တမလွန်ဘဝသို့ ကူးပြောင်းသည်။','“သီုကဵုဗောဓိသတ် တိုၚ်ပွဇကုဟေၚ် စဴအာဘဝပလိုက်ရ။” (ဇ—၂၉။ အစွောံ။) = “ဘုရားလောင်းသည်လည်း မိမိပြုအပ်သော ကောင်းမှုမကောင်းမှုအတိုင်း ကံအားလျော်စွာ ဘဝတစ်ပါး သို့လား၏။” || “(ဗောဓိသတ်ဇာဒိသိုၚ်) ပ္ဍဲလအိတ်အာယုက် လၟေၚ်ပရေၚ်ကံဂှ် စဴအာဘဝပလိုက် ရ။” (ဇ—၁၅၂။ အစွောံ။) = “ဘုရားလောင်းခြင်္သေ့သည် အသက်၏အဆုံး­ ကံအားလျော်စွာ လား၏။”')
,(3940,3,4,'(ရဟန်း၊ ဘုရင်စသည့်မြင့်မြတ်သူတို့) စုတေကွယ်လွန်သည်။ နတ်ရွာစံသည်။',NULL)
,(3941,3,4,'စမ်းသည်။ စမ်းသတ်သည်။',NULL)
,(3942,3,9,'အမိန့်ပေးရာ­၄င်း တိုက်တွန်းပြောဆိုရာ­၄င်း ကြိယာကို ပိုမိုလေးနက်အောင် ထောက်ပံ့သောစကားလုံး။','‘အာထောံစမ်’ = ‘သွားစမ်း။ || “စစမ်ရံၚ်ညိစမ်။” = “မြီးစားကြည့်စမ်းပါ။”')
,(3943,3,4,'စိတ်ကိုစမ်းသည်။',NULL)
,(3944,3,4,'စမ်းသပ်သည်။ စုံစမ်းသည်။','“ပဟိုတ်ကဵုဗမၞးသၟိက်စံၜတ်ဓဝ်သဳလဂှ်တုဲ သဳလဝိမံသဇာတ် ကျာ်တြဲတွံ။” (ဇ—၂၉ဝ။ အစွောံ။) = “ဤသီလဝိမံသဇာတ်ကို — သီလကိုစုံစမ်းသော တယောက်သောပုဏ္ဏားကို အကြောင်းပြု၍ ဟောတော်မူ၏။” (ညောင်ကန်) || “အ္စာသဝ်စံၜတ်မၞိဟ်ယဲ။” = “ဆရာဝန်က လူနာကို စမ်းသပ်သည်။”')
,(3945,3,1,'၁။ ကျော။ နောက်ကျော။',NULL)
,(3945,3,1,'၂။ မြစ်။ မြေး၏သားသမီး။','‘ကောန်စဴစးဒပှ်ဒတောဝ်။’ (ဇ—၁၅၇။ အစွောံ။) = ‘သားမြေးမြစ်ခုနစ်ဆက်။’')
,(3946,3,4,'၁။ ဆန့်ကျင်သည်။ ဖီဆန်သည်။ လွန်ဆန်သည်။','စးအသမ် = အမိန့်ဖီဆန်သည်။ || စးဂလာန်မိမ၊ စးပါၚ်မိမ = မိဘစကားကို ဖီဆန်သည်။ || “မိတ္တဝိန္ဒကဝွံ ဟိုတ်ဒေါသမာနသၠုၚ်တုဲ စးကၠေံပါၚ်မိတုဲ ဂျိုၚ်ၚ်မဒးနရက်ရောၚ် ဟွံသေၚ်ဟာ။” (ဇ—၁ဝ၄။ အစွောံ။) = “မိတ္တဝိန္ဒ ကလုလင်သည် ဒေါသမာနကြီးသောကြောင့် မိခင်၏စကားကို လွန်ဆန်သဖြင့် အရှင်လတ်လတ် ငရဲခံရသည်မဟုတ်လော။”')
,(3946,3,4,'၁။ ဆန့်ကျင်သည်။ ဖီဆန်သည်။ လွန်ဆန်သည်။','“ဒုဟ်မစးတၠပညာဝွံ ညံၚ်တၠယဲမစးပါၚ်သဝ်တၠဒယှ် မဒးညာတ်ဂစိုတ်ကီု ဒှ်ဟိုတ်လေၚ်လၞီဒဒိုက်စၟတ်ရ—။” (ဇ—၁၃၃။ အစွောံ။) = “ပညာရှိအား ဖီဆန်ခြင်းအပြစ်သည်ကား ဆေးသမားကျော်၏စကားကို ဖီဆန်သောလူနာရှင်သည် (လူနာ၏)သေခြင်းကို မြင်ရသကဲ့သို့ ပျက်စီးဆုံးရှုံးရခြင်း၏ အကြောင်းတရားအမှန်ပင်တည်း။” || “ညံၚ်တၠယဲမဟွံစးပါၚ် သဝ် မဂွံဗၠးယဲကီု လ္ပစးပါၚ်တၠပညာညိ။” (ဇ—၁၄၁။ အစွောံ။) = “ဆေးသမား၏စကားကို မဖီ ဆန်သောလူနာသည် ရောဂါပျောက်ကင်းရသကဲ့သို့ ပညာရှိစကားကို မလွန်ဆန်ပါလေနှင့်။”')
,(3946,3,4,'၂။ ဆန်တက်သည်။','စးဍာ် = ရေဆန်ဖြင့်သွားသည်။')
,(3947,3,1,'ခြေဖမိုး။',NULL)
,(3948,3,1,'လက်ဖမိုး။',NULL)
,(3949,3,11,'(န) ၁။ စက်။','စက်ဂၠုၚ် = လှေစက်။ || စက်ဇၟိၚ် = အပ်ချုပ်စက်။ || စက်ဗဝ် မှဝ် = အိုးထိန်းစက်။')
,(3949,3,11,'(န) ၂။ လုံးဝန်းသောအရာ။ စက်ဝိုင်းပုံရှိသောအရာ။','စက်ဂိတု = လဝန်း။ || စက်တ္ၚဲ = နေဝန်း။ || စက်ကွဳ = လှည်းဘီး။ (ရှေးသုံး)')
,(3950,3,10,'(န) စကြာဝဠာ။','စှ်လ္ၚီစက္ကဝါ = စကြာဝဠာတစ်သောင်းတိုက်။')
,(3951,3,1,'နတ်ရထား။',NULL)
,(3952,3,1,'စက္ကဝါက်ငှက်။',NULL)
,(3953,3,1,'စကြဝတေးမင်း။',NULL)
,(3954,3,13,'(န) စစ်ကဲ။ စစ်သူကြီး။ ရှေးခေတ်စစ်အရာရှိကြီးတစ်မျိုး။',NULL)
,(3955,3,1,'၁။ (ပြုံးရယ်သည့်အခါ ပါးတွင်ဖြစ်ပေါ်သော) ပါးချိုင့်။',NULL)
,(3955,3,1,'၁။ ၂။ ပါးကွက်။','(ပါးပြင်ပေါ်တွင် အဝိုင်းပုံလိမ်းထားသော သနပ်ခါးအကွက်။)')
,(3956,3,1,'လေရဟတ်။',NULL)
,(3957,3,1,'(ဆင်ကိုထိုးချိတ်ရသော) ချွန်း။ ချွန်းတောင်း။',NULL)
,(3958,3,10,'(န) မျက်စိ။',NULL)
,(3959,3,10,'(န) ၁။ မျက်စိထဲတွင် ရူပါရုံအရိပ်ထင်ရာဓါတ်။',NULL)
,(3959,3,10,'(န) ၂။ မျက်စိအမြင်တွင် တင့်တယ်မှု။ စက္ခုပသာဒ။',NULL)
,(3960,3,1,'စက္ကူ။','စက္ခောပၠုဲ = ဖယောင်းစက္ကူ။')
,(3961,3,1,'စက်ဝိုင်း။',NULL)
,(3962,3,1,'ဇာတာခွင်။ ဗေဒင်က္ခတ်ဇာတာစက်။',NULL)
,(3963,3,1,'လဝန်း။',NULL)
,(3964,3,1,'၁။ လေရဟတ်။ လည်ပတ်သောစကြာ။ (ပါဠိ—စိဂုVလက)',NULL)
,(3964,3,1,'၂။ ပုစဉ်း၊ ပုရစ်တို့ကဲ့ သို့သော ပျံသန်းနိုင်သော ပိုးကောင်တစ်မျိုး။ (?)',NULL)
,(3965,3,1,'မာယာပရိယာယ်စက်ကွင်း။ ကောက်ကျစ်စွာဆင်ထားသောအကွက်။','“နညာဏ်ဗစာရဏာ ၚဳဂၠာဲရံၚ်စက်စၞာဲညးတုဲ ဂွံတီကေတ်စၞာဲညး—။” (ဇ—၉၈။ အစွောံ။) = “သူတစ်ပါး၏မာယာစက်ကွင်းကို ဉာဏ်ပညာဖြင့် ရှာဖွေပိုင်းခြားဆင်ခြင်ပြီး သူတစ်ပါး၏မာယာကိုသိ၍—။”')
,(3966,3,1,'သံသရာစက်။ (?)',NULL)
,(3967,3,1,'လက်ဗွေ။ လက်ဗွေရာ။',NULL)
,(3968,3,1,'နေဝန်း။','“နူဂယးပြဟ် ကၠာစက်တ္ၚဲဟွံတိုန် (လၟ) ပြာၚ်လဝ်ပးဓနက်—။” (ဇ—၁၅၉။ အစွောံ။) = “နံနက်စောစော နေဝန်းမတက်မီ မုဆိုးသည် ကျော့ကွင်းထောင်ထား၏။”')
,(3969,3,1,'စက်ယန္တရား။',NULL)
,(3970,3,1,'ရာသီစက်။ တစ်ဆယ့်နှစ်ရာသီအဝန်း။',NULL)
,(3971,3,1,'လျှာစက်။',NULL)
,(3972,3,1,'အိုးထိန်းစက်။ (ပါဠိ—ကုလာလဘဏ္ဍ','ကုလာလစက္က)')
,(3973,3,4,'စုတ်ပြဲသည်။','“ပလောအ်စာ်အာရ။” = “အင်းကျီစုတ်သွားပြီ။”')
,(3974,3,4,'ကွဲကွာသည်။ ကွေကွင်းသည်။','“ပ္ဍဲကာလဗ္တံ တ္ၚဲဂၠုအာဂှ် ပိုဲမဒးစာ်ခြာတုဲ ဟွံဂွံညာတ် ရၚ်သ္ကအ်ရ” ခၞောဝ်ဗြဴဂး။ = “မိုးချုပ်သွားသော ညဉ့်အချိန်­ ကျွန်ုပ်တို့ကွဲကွာ၍ တစ်ယောက်နှင့်တစ်ယောက် မမြင်ကြရပါ” ဟုကိနနရဳမ ဆို၏။')
,(3975,3,4,'စုတ်ပြဲသည်။ စုတ်ပြတ်သည်။ ပေါက်ပြဲသည်။','“တၠအဲမံၚ်ပ္ဍဲဂြိုပ်မွဲဇကု သၞာသၠဆု စာ်ဂြာတ် ပ္ဍဲဒေါဝ်သၟတ်ဒြုန်မဂၠိုၚ် မဒးသတိက်ဂှ် မူအသဝ်ဍေံသၞုံရော။” (ဇ—၅၃၇။ အစွောံ။) = “သင်သည် တော­တစ်ကိုယ်တည်းနေ၍ စုတ်ပြတ်သောသစ်ရွက်အခင်းတွင် ပိုးခြပုရွက်များအကြား­ အိပ်စက်ရခြင်းသည် အဘယ်အံ့ဖွယ်ရှိအံ့နည်း။” || ‘စာ်ဓရာတ်’ နှင့်အတူတူ။')
,(3976,3,4,'၁။ ကွဲကွာသည်။ ကွေကွင်းသည်။','“စာ်စ္ဍးနူမိတုဲ အဲမံၚ်ဟွံမိပ်ရ။” = “အမေနှင့်ကွဲကွာ၍ ကျွန်တော်နေမပျော်ပါ။” || “ၜိုန်ခနှောဝ်မဒှ်တိရစ္ဆာန်ကီုလေဝ် မဒးစာ်စ္ဍးအာ ဆဗၞတ်မွဲဗ္တံကီုဂှ် လုကဴထပှ်ကၠံသၞာံ ဗန်ရၚ်သ္ကံတုဲ မဒးယာံဒက်ဒေါန်တဴကဵုရၚ်သ္ကံတုဲရ။” (ဇ—၅ဝ၄။ အစွောံ။) = “တိရစ္ဆာန်ဖြစ်ကုန်သော ဤကိနနရာတို့စဉ်လျက်လည်း တညဉ့်မျှကင်း၍နေရသဖြင့် အနှစ်ခုနစ်ရာတို့ပတ်လုံး လည်ဖက်ကာငိုကြွေးလျက် သွားကြကုန်၏။”')
,(3976,3,4,'၂။ ကင်းမဲ့သည်။ မရှိဖြစ်သည်။','“ပူဂဵုသမၠီုမစာ်စ္ဍးအာနူပညာဂှ် လလေၚ်ဇကုကီု လလေၚ်ညးကီု ဏာဗစိုပ်ဟေၚ်ရ။” = “ပညာမှကင်းသောသူမိုက်သည် မိမိပျက်စီးခြင်းကို၄င်း သူတစ်ပါးပျက်စီးခြင်းကို၄င်း ရောက်ရှိစေ၏။” || “တဳလပစ္စေဂဗုတ်ဂှ် မစာ်စ္ဍးအာနူဓဝ်ရာဂတုဲရ။ ဟၟဲကဵုသရာံပါပ်တုဲရ။” (ဇ—၄၉၆။ အစွောံ။) = “အရှင်ပစ္စေကဗုဒ္ဓါသည် ရာဂတရားမှ ကင်းခဲ့ပြီ။ မကောင်းမှုဟူ၍ မရှိတော့ပြီ။”')
,(3976,3,4,'၃။ (အနာရောဂါ) ကင်းဝေးသည်။','“မံၚ်သ္အးဇ္ၚးမ္ဂး ယဲဘဲစာ်စ္ဍးရ။” = “သန့်ရှင်းစွာနေထိုင်လျှင် ရောဂါကင်းဝေးသည်။”')
,(3977,3,4,'စုတ်ပြဲသည်။ စုတ်ပြတ်သည်။','“မိကဵုမ (တ္ၚေက်) ၜါမဗျု ဍိုန်အာကဵုဒြဟတ်ဂှ် ဂၠးသၞေၚ်ၜါစာ်ဓရာတ်ပြဟ်အာတြ။ ဂးဒြဟတ်လေဝ်ဍိုန် အာကၠုၚ်ဟွံမာန်ရ။” (ဇ—၄၈၄။ အစွောံ။) = “ငါ၏ (ကျေးသား) မိဘနှစ်ပါးတို့သည်ကား အိုမင်းအားနည်းကုန်သည်ဖြစ်၍ တောင်ပံနှစ်ဖက် တို့သည်လည်း စုတ်ပြဲပြတ်ကြွေသွားကုန်ပြီ။ အားအင်လည်းချိနဲ့၍ မသွားလာနိုင်ကြတော့ပြီ။”')
,(3978,3,3,'ယုတ်ညံ့စုတ်ပြတ်သော။ စုတ်ပြဲညစ်နွမ်းသော။','ယာတ်မစာ်သၟာ် = စုတ်ပြတ်ညစ်နွမ်းသောအဝတ်။')
,(3979,3,1,'၁။ မင်ကြောင်၊ စုတ်ဆေး စသည်ထိုးနှံသော အသွားခွဲစိတ်ထားသည့် သံချွန်စုတ်တံ။',NULL)
,(3979,3,1,'၂။ ပန်းချီဆွဲရန်၊ ဆေးသုတ်ရန် အမွေးအမှၚ်တို့ကို စုစည်းပြုလုပ်ထားသောစုတ်တံ။',NULL)
,(3980,3,4,'၁။ ထိမိသည်၊ ထိစပ်နီးကပ်သည်။','“သ္ၚိဍေံကဵုသ္ၚိအဲ စုက်ဒၟံၚ်ရ။” = “သူ့အိမ်နှင့် ငါ့အိမ်တို့သည် ထိစပ်နီးကပ်နေသည်။”')
,(3980,3,4,'၂။ (ဦးချိုရှိသောတိရစ္ဆာန်) ဦးချိုဖြင့်ထိုးဝှေ့သည်။ ခတ်သည်။','“ဗ္ၜေံဒမြိုဟ်မွဲဒြေပ်ကၠုၚ် စုက်စုတ်(ခမဳဗြဴဂှ်)တုဲ ဇိုၚ်ဂှ်ကဝ်အာ။”(ဇ—၁၁၅။ အစွောံ။) = “ထိုကြမ်းသောဆိတ်သည် ပြေးလာပြီးလျှင် ဦးချိုနှင့်ထိုးဝှေ့၍ ထိုရဟန်းမိန်းမသည် ခြေကျိုးသွား၏။”')
,(3980,3,4,'၃။ (ဦးခေါင်းဖြင့်) ဝင်ကျုံးသည်။ ဝှေ့သည်။ ခတ်သည်။','“ထေရ်ဗျုဂှ် ကွာ်အာဍိုန်ဍိုန်တုဲ သာမဏဳကောန်ဂှ် စုက်ကဵုက္ဍိုပ်တုဲ ‘ကမန်အာ ကမန်အာ’ ဂးတုဲ စုက်ဒလူ ဏာထေရ်ဗျုမဒှ်မဂှ်ရ။” (ဇ—၃၁၂။ အစွောံ။) = “ရဟန်းအိုကြီးသည် ဖြည်းဖြည်းနှေးနှေး လျှောက်နေရာ သားဖြစ်သောသာမဏေက ဦးခေါင်းဖြင့်ခတ်၍ ‘မြန်မြန်သွား မြန်မြန်သွား’ ဟု ဆိုကာ အဘဖြစ်သောရဟန်းအိုကို ခေါင်းဖြင့်ဝှေ့၍ ရှေ့သို့တွန်းထိုး၏။”')
,(3981,3,5,'နီးနီးကပ်ကပ်။','“ပိုဲမံၚ်စုက်စုက်ညးသ္ကအ်မ္ဂး ခိုဟ်ရောၚ်။” = “ကျွန်တော်တို့ နီးနီးကပ်ကပ်နေကြလျှင် ကောင်းမည်။”')
,(3982,3,4,'ထိမိသည်။ နီးစပ်သည်။',NULL)
,(3983,3,1,'မြေး၏သားသမီး။ မြစ်။',NULL)
,(3984,3,1,'ဝဲယားနာ။',NULL)
,(3985,3,1,'သစ်သီးချူရန် တံချူထိပ်တွင် တပ်ဆင်ထားသောခြင်းကလေး။','(ကြိ) ကျီစယ်သည်။')
,(3986,3,4,'ဆိုသည်။ ဟူသည်။ ဤသို့ကြားဖူးသည်ကား။ တစ်ဆင့်စကားကြားဖူးသည်ကား။ (ပါဠိ—ကိရ)','“ညးကၠေံဒၟံၚ်ဗၞတ်ပိသၞာံရ။ စံက်ဂးညးချိုတ်အာဣရ။” = “သူပျောက်နေသည်မှာ သုံးနှစ်ရှိပြီ။ သူသေသွားပြီဟု ဆိုသည် (ဝါ) တစ်ဆင့်စကားကြားရသည်။”')
,(3987,3,4,'ဟူသတတ်။ ဆိုသတဲ့။ တစ်ဆင့်စကားကြားရသည်ကား။','“စံက်ဂးကျာ် ဇၞော်ကွာန်ပိုဲ ပဝ်အာရယး။” = “ငါတို့ရွာဆရာတော် ပျံလွန်တော်မူပြီဆိုသတဲ့။”')
,(3988,3,4,'ကျီစယ်သည်။ ကလူသည်။',NULL)
,(3989,3,1,'ဘုမ္မရာဇာ။ (အမြစ်အရသာခါး၍ အလွန်ဆေးဖက်ဝင်သော အပင်ငယ်တစ်မျိုး)',NULL)
,(3990,3,4,'ကလိထိုးသည်။',NULL)
,(3990,3,1,'ကလိထိုးခြင်း။','ထပက်စံက်လေက် = ကလိထိုးသည်။')
,(3991,3,4,'ထုပ်ပိုးသည်။',NULL)
,(3991,3,9,'အထုပ်ကိုရေတွက်ရာတွင် သုံးသောစကားလုံး။','ဂၠိက်ယာတ် ၜါစိုက် = အဝတ်အစားထုပ်နှစ်ထုပ်။')
,(3992,3,1,'ခါးပိုက်။',NULL)
,(3993,3,1,'အထုပ်အပိုး။',NULL)
,(3994,3,1,'စၚ်။','စၚ်ဂတေက် = လွှစင်။ စၚ်ပေဲါ = ပွဲစင်။ စၚ်လဵု = ဗူးစင်။')
,(3994,3,4,'ချွန်ထက် သောအရာနှင့် ထိုးဖေါက်သည်။',NULL)
,(3995,3,4,'နားပေါက်ထွင်းသည်။',NULL)
,(3996,3,12,'(န) စင်္ကြံ။','“ပ္ဍဲသ္ကဲစင်္ကြံဣသိဂှ် တၞအ်ဒြုန်မွဲနွံ။” = “ရသေ့၏စင်္ကြံနံဘေး­ ခြတောင်ပို့တစ်ခုရှိ၏။” || ကွာ်စၚ်ကြံ = စင်္ကြံလျှောက်သည်။')
,(3996,3,12,'(ကြိ) စင်္ကြံလျှောက်သည်။','“ဥပးဂှ် စၚ်ကြံဒၟံၚ်။” (ဇ—၇၆။ အစွောံ။) = “ထိုသီတင်းသည်သည် စင်္ကြံလျှောက် နေ၏။”')
,(3997,3,4,'၁။ စဉ်းစားဆင်ခြင်သည်။','“ပတွဵုနူဂှ်တုဲ လဟီုမွဲဒၞာဲမဟီုဂှ် စၚ်ခြၚ်စမ်ၜတ်တုဲ မဟီုရ။” (ဇ—၃၃၁။ အစွောံ။) = “ထိုအခါမှစ၍ တစ်စုံတစ်ခုကို ပြောဆိုသောအခါ ဆင်ခြင်သုံး သပ်ပြီးမှ ပြော၏။” || “ပွမွဲပဟွံဒး မသ္ၚောံကြဴဂှ် စၚ်ခြၚ်နပညာညိ။” (ဇ—ဝိဓုရ။ အစွောံ။) = “နောင်ကိုစိုးရိမ်ပူပန်ရမည့် မလျောက်ပတ်သော အမှုတစ်ခုကိုမပြုမီ ပညာဖြင့်ဆင်ခြင်ပါ။”')
,(3997,3,4,'၁။ စဉ်းစားဆင်ခြင်သည်။',NULL)
,(3997,3,4,'၂။ တိုင်ပင်သည်။ ဆွေးနွေးသည်။ စည်းဝေးသည်။','“သၟိၚ်စၚ်ခြၚ်ကဵုအမာတ်တံဂမၠိုၚ်။” (ဇ—၁၃၁။ အစွောံ။) = “မင်းသည် မှူးမတ်များနှင့် တိုင်ပင်၏။” || “ပ္ဍဲဍုၚ်ရာဇာဂြိုဟ် နမမိက်ကဵုစရၚ်မွဲညိညဂှ် ပ္ဍဲဇြပ်မစၚ်ခြၚ်ဂှ် ဂကောံမှာဇန်ဂမၠိုၚ် ကၠုၚ်ကောံအိုတ်ရ။” (ဇ—၄၅၃။ အစွောံ။) = “ရာဇဂြိုဟ်ပြည်­ တစ်စုံတစ်ခုသောပြုဖွယ်ကိစ္စကြောင့် စည်းဝေးတိုင်ပင်ရာဇရပ်­ လူအပေါင်းတို့သည် ရောက်လာစည်းဝေးကြကုန်၏။”')
,(3998,3,4,'(ကျွဲနွားစသည်ကို) နဖားထိုးသည်။ နဖားတပ်သည်။',NULL)
,(3999,3,1,'၁။ ချေးထိုးပိုး။',NULL)
